import { addCashMovement, assignMemberBranch, cancelSale, checkPlatformAdmin, closeCash, createAttendanceCategory, createAttendanceEmployee, createBranch, createCustomer, createPlatformBusiness, createProduct, deleteInvitation, deletePlatformBusiness, ensureAttendanceKiosk, getAttendanceKioskData, inviteTeamMember, loadAttendanceAdmin, loadBranchControl, loadBranches, loadCash, loadCashClosureMovements, loadCashClosureReports, loadControlInventory, loadControlMovements, loadCustomers, loadPlatformBusinesses, loadPlatformSummary, loadPurchases, loadSales, loadStore, loadTeam, markAttendance, openCash, receivePurchase, resendPlatformInvitation, returnSale, switchBranch, updateAttendanceEmployee, updateBranch, updatePlatformBusiness, updateTeamMember, type AttendanceCategory, type AttendanceEmployee, type AttendanceEvent, type Branch, type BranchReport, type CashClosureReport, type CashData, type ControlInventory, type ControlMovement, type Customer, type LiveSale, type PlatformBusiness, type PlatformSummary, type Purchase, type StoreProfile, type TeamInvitation, type TeamMember } from './lib/store'
import { api } from './lib/api'
