type Page = 'Resumen'|'Centro de control'|'Vista general'|'Movimientos'|'Cierres de caja'|'Inventario global'|'Sucursales'|'Usuarios'|'Punto de venta'|'Productos'|'Compras'|'Clientes'|'Caja'|'Reportes'|'Configuración'
const nav: {name:Page;icon:any}[] = [
  {name:'Resumen',icon:LayoutDashboard},{name:'Centro de control',icon:BarChart3},{name:'Punto de venta',icon:ShoppingCart},{name:'Productos',icon:Package},{name:'Compras',icon:Truck},{name:'Clientes',icon:Users},{name:'Caja',icon:WalletCards},{name:'Reportes',icon:BarChart3}
]
const corporateNav:{name:any;icon:any}[]=[{name:'Vista general',icon:LayoutDashboard},{name:'Movimientos',icon:RefreshCw},{name:'Cierres de caja',icon:ReceiptText},{name:'Inventario global',icon:Boxes},{name:'Asistencia',icon:CalendarDays},{name:'Sucursales',icon:Store},{name:'Usuarios',icon:Users}]
const access:Record<string,Page[]>={admin:['Resumen','Centro de control','Punto de venta','Productos','Compras','Clientes','Caja','Reportes','Configuración'],supervisor:['Resumen','Centro de control','Punto de venta','Productos','Compras','Clientes','Caja','Reportes'],cashier:['Resumen','Punto de venta','Clientes','Caja'],warehouse:['Resumen','Productos','Compras']}
const canSee=(role:string|undefined,page:Page)=>!role||access[role]?.includes(page)
const roleLabel=(role:string|undefined)=>({admin:'Administrador central',supervisor:'Supervisor',cashier:'Cajero',warehouse:'Bodega'}[role??'']??'')
type CorporateView='overview'|'movements'|'cashClosures'|'inventory'|'attendance'|'branches'|'team'
const corporateViews:Record<string,CorporateView>={'Vista general':'overview','Movimientos':'movements','Cierres de caja':'cashClosures','Inventario global':'inventory','Asistencia':'attendance','Sucursales':'branches','Usuarios':'team'}
const corporateView=(page:Page|string)=>corporateViews[page]

export default function App(){
  const [session,setSession]=useState<Session|null>(null)
  const [authReady,setAuthReady]=useState(!isSupabaseConfigured)
  const [passwordSetup,setPasswordSetup]=useState(false)
  const attendanceToken=new URLSearchParams(window.location.search).get('attendance')
  useEffect(()=>{
    if(!supabase)return
    const invited=window.location.search.includes('invite=1')||window.location.hash.includes('type=invite')||window.location.hash.includes('type=recovery')
    setPasswordSetup(invited)
    supabase.auth.getSession().then(({data})=>{setSession(data.session);setAuthReady(true)})
    const {data}=supabase.auth.onAuthStateChange((_event,next)=>setSession(next))
    return()=>data.subscription.unsubscribe()
  },[])
  if(attendanceToken)return <AttendanceKiosk token={attendanceToken}/>
  if(!authReady)return <div className="app-loading"><div className="brand-mark"><Store/></div><span>Cargando MUNDO MEGA...</span></div>
  if(isSupabaseConfigured&&!session)return <AuthScreen/>
  if(isSupabaseConfigured&&session&&passwordSetup)return <PasswordSetup done={()=>{window.history.replaceState({},'',window.location.origin);setPasswordSetup(false)}}/>
  return <AuthenticatedApp/>
}

function AuthenticatedApp(){
  const [page,setPage]=useState<Page>('Resumen'); const [mobile,setMobile]=useState(false)
  const [catalog,setCatalog]=useState<Product[]>([]); const [profile,setProfile]=useState<StoreProfile|null>(null); const [storeError,setStoreError]=useState(''); const [initialRouted,setInitialRouted]=useState(false);const [platformAdmin,setPlatformAdmin]=useState(false);const [portal,setPortal]=useState<'loading'|'platform'|'business'>('loading')
  const refresh=async()=>{try{const data=await loadStore();setProfile(data.profile);setCatalog(data.products);setStoreError('')}catch(e){setStoreError(e instanceof Error?e.message:'No fue posible cargar los datos')}}
  useEffect(()=>{Promise.all([refresh(),checkPlatformAdmin()]).then(([,isAdmin])=>{setPlatformAdmin(isAdmin);setPortal(isAdmin?'platform':'business')}).catch(e=>{setStoreError(e instanceof Error?e.message:'No fue posible iniciar');setPortal('business')})},[])
  useEffect(()=>{if(profile&&!initialRouted){if(profile.role==='admin')setPage('Vista general');setInitialRouted(true)}},[profile,initialRouted])
  if(portal==='loading')return <div className="app-loading"><div className="brand-mark"><Store/></div><span>Preparando tu espacio…</span></div>
  if(platformAdmin&&portal==='platform')return <PlatformAdminPortal enterBusiness={()=>setPortal('business')}/>
  return <div className="app-shell">
    <aside className={mobile?'sidebar open':'sidebar'}>
      <div className="brand"><div className="brand-mark"><Store size={22}/></div><div><b>Grupo Multimarkets S.A.</b><span>MUNDO MEGA</span></div><button className="mobile-close" onClick={()=>setMobile(false)}><X/></button></div>
      {profile?.role==='admin'?<div className="corporate-side-label"><BarChart3/><div><small>Portal activo</small><strong>Centro corporativo</strong></div></div>:<BranchSwitcher profile={profile} refresh={refresh}/>} 
      <nav>{(profile?.role==='admin'?corporateNav:nav.filter(n=>canSee(profile?.role,n.name))).map(n=><button key={n.name} className={page===n.name?'active':''} onClick={()=>{setPage(n.name);setMobile(false)}}><n.icon size={19}/><span>{n.name}</span>{n.name==='Productos'&&<em>3</em>}</button>)}</nav>
      <div className="side-bottom">{platformAdmin&&<button className="platform-return" onClick={()=>setPortal('platform')}><Globe2/><span>Panel multiempresa</span></button>}<div className="profile"><div className="avatar">{profile?.fullName?.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()??'--'}</div><div><strong>{profile?.fullName??'Cargando…'}</strong><span>{roleLabel(profile?.role)}</span></div><button className="profile-logout" title="Cerrar sesión" onClick={()=>supabase?.auth.signOut()}><LogOut size={16}/></button></div></div>
    </aside>
    {mobile&&<div className="backdrop" onClick={()=>setMobile(false)}/>} 
    <main><Topbar title={page} openMenu={()=>setMobile(true)}/><div className="page-content">
      {storeError&&<div className="system-alert"><AlertTriangle/>{storeError}</div>}{page==='Resumen'&&<Dashboard go={setPage} profile={profile} catalog={catalog}/>} {page==='Centro de control'&&<ControlHub profile={profile} refreshStore={refresh}/>} {corporateView(page)&&<ControlHub profile={profile} refreshStore={refresh} view={corporateView(page)}/>} {page==='Punto de venta'&&<POS catalog={catalog} profile={profile} refresh={refresh}/>} {page==='Productos'&&<Products catalog={catalog} profile={profile} refresh={refresh}/>} 
      {page==='Compras'&&<Purchases profile={profile} catalog={catalog} refreshProducts={refresh}/>} {page==='Clientes'&&<Customers profile={profile}/>} {page==='Caja'&&<Cash profile={profile}/>} {page==='Reportes'&&<Reports profile={profile}/>} {(page as string)==='Asistencia'&&profile&&<ControlHub profile={profile} refreshStore={refresh} view="attendance"/>} {page==='Configuración'&&<SettingsPage profile={profile} refreshStore={refresh}/>} 
    </div></main>
  </div>
}

type PlatformSection='dashboard'|'businesses'
const industryLabels:Record<string,string>={retail:'Comercio general',minimarket:'Minimarket',pharmacy:'Farmacia',hardware:'Ferretería',clothing:'Ropa y calzado',restaurant:'Restaurante',services:'Servicios',other:'Otro'}
const planLabels:Record<string,string>={starter:'Inicial',business:'Negocios',enterprise:'Empresarial'}
const statusLabels:Record<string,string>={pending:'Pendiente',active:'Activa',suspended:'Suspendida',cancelled:'Cancelada'}

function PlatformAdminPortal({enterBusiness}:{enterBusiness:()=>void}){
  const [section,setSection]=useState<PlatformSection>('dashboard');const [summary,setSummary]=useState<PlatformSummary|null>(null);const [rows,setRows]=useState<PlatformBusiness[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [open,setOpen]=useState(false);const [q,setQ]=useState('')
  const refresh=async()=>{setLoading(true);setError('');try{const [s,b]=await Promise.all([loadPlatformSummary(),loadPlatformBusinesses()]);setSummary(s);setRows(b)}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar la plataforma')}finally{setLoading(false)}}
  useEffect(()=>{refresh()},[])
  const shown=rows.filter(b=>(b.name+' '+b.legalName+' '+industryLabels[b.industry]).toLowerCase().includes(q.toLowerCase()))
  return <div className="platform-shell"><aside className="platform-sidebar"><div className="platform-brand"><div className="brand-mark"><Globe2/></div><div><b>Grupo Multimarkets</b><span>PLATAFORMA SaaS</span></div></div><div className="platform-owner"><ShieldCheck/><div><small>Acceso propietario</small><b>Administrador general</b></div></div><nav><button className={section==='dashboard'?'active':''} onClick={()=>setSection('dashboard')}><LayoutDashboard/>Vista general</button><button className={section==='businesses'?'active':''} onClick={()=>setSection('businesses')}><Building2/>Empresas <em>{summary?.businesses??0}</em></button></nav><div className="platform-side-bottom"><button onClick={enterBusiness}><Store/>Entrar a MUNDO MEGA</button><button onClick={()=>supabase?.auth.signOut()}><LogOut/>Cerrar sesión</button></div></aside><main className="platform-main"><header className="platform-top"><div><span>CENTRO DE ADMINISTRACIÓN</span><h1>{section==='dashboard'?'Panel multiempresa':'Empresas y clientes'}</h1></div><div><button className="secondary" onClick={refresh}><RefreshCw className={loading?'spin':''}/>Actualizar</button><button className="primary" onClick={()=>setOpen(true)}><Plus/>Nueva empresa</button></div></header><div className="platform-content">{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}{section==='dashboard'?<PlatformDashboard summary={summary} rows={rows} loading={loading} goCompanies={()=>setSection('businesses')}/>:<PlatformBusinesses rows={shown} q={q} setQ={setQ} loading={loading} refresh={refresh}/>}</div></main>{open&&<NewBusinessDialog close={()=>setOpen(false)} saved={async()=>{setOpen(false);await refresh();setSection('businesses')}}/>}</div>
}

function PlatformDashboard({summary,rows,loading,goCompanies}:{summary:PlatformSummary|null;rows:PlatformBusiness[];loading:boolean;goCompanies:()=>void}){
  const industries=rows.reduce<Record<string,number>>((a,b)=>({...a,[b.industry]:(a[b.industry]??0)+1}),{})
  return <><div className="platform-welcome"><div><span>CONTROL TOTAL, DATOS SEPARADOS</span><h2>Tu red de empresas en un solo lugar</h2><p>Cada cliente trabaja en un espacio privado con sus propias ventas, usuarios, sucursales e inventario.</p></div><div className="privacy-seal"><ShieldCheck/><div><b>Aislamiento activo</b><small>Protegido por Supabase RLS</small></div></div></div><div className="platform-metrics"><PlatformMetric label="Empresas" value={summary?.businesses??0} note={`${summary?.activeBusinesses??0} activas`} icon={Building2}/><PlatformMetric label="Sucursales" value={summary?.branches??0} note="En toda la plataforma" icon={Store}/><PlatformMetric label="Usuarios" value={summary?.users??0} note="Cuentas activas" icon={Users}/><PlatformMetric label="Ventas de hoy" value={money(summary?.salesToday??0)} note="Total de la red" icon={CircleDollarSign}/></div><div className="platform-grid"><section className="card platform-companies-card"><CardHead title="Empresas recientes" sub="Estado de incorporación de tus clientes" action={<button className="link-btn" onClick={goCompanies}>Ver todas <ArrowUpRight/></button>}/>{loading?<div className="empty-table"><RefreshCw className="spin"/>Cargando empresas…</div>:rows.slice(0,6).map(b=><div className="platform-company-row" key={b.id}><div className="company-logo" style={{background:b.primaryColor}}>{b.name.slice(0,2).toUpperCase()}</div><div><b>{b.name}</b><span>{industryLabels[b.industry]} · {b.branches} sucursal{b.branches===1?'':'es'}</span></div><span className={`tenant-status ${b.status}`}>{statusLabels[b.status]}</span><strong>{planLabels[b.plan]}</strong></div>)}</section><section className="card platform-niches"><CardHead title="Empresas por nicho" sub="Distribución actual"/>{Object.entries(industries).length===0?<div className="empty-table"><Building2/>Aún no hay empresas</div>:Object.entries(industries).sort((a,b)=>b[1]-a[1]).map(([key,value])=><div className="niche-row" key={key}><span>{industryLabels[key]}</span><div><i style={{width:`${Math.max(12,value/rows.length*100)}%`}}/></div><b>{value}</b></div>)}</section></div></>
}
function PlatformMetric({label,value,note,icon:Icon}:{label:string;value:string|number;note:string;icon:any}){return <div className="card platform-metric"><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div><div><Icon/></div></div>}

function PlatformBusinesses({rows,q,setQ,loading,refresh}:{rows:PlatformBusiness[];q:string;setQ:(v:string)=>void;loading:boolean;refresh:()=>Promise<void>}){
  const [busy,setBusy]=useState('');const [error,setError]=useState('');const [editing,setEditing]=useState<PlatformBusiness|null>(null)
  const change=async(b:PlatformBusiness,status:string)=>{const action=status==='suspended'?'suspender':status==='active'?'activar':'actualizar';if(!confirm(`Deseas ${action} ${b.name}?`))return;setBusy(b.id);setError('');try{await updatePlatformBusiness(b.id,{status});await refresh()}catch(e){setError(readError(e,'No fue posible actualizar'))}finally{setBusy('')}}
  const remove=async(b:PlatformBusiness)=>{if(!confirm(`Eliminar ${b.name}? Se bloqueara el acceso y dejara de aparecer en el panel. Los datos historicos se conservan.`))return;setBusy(b.id);setError('');try{await deletePlatformBusiness(b.id);await refresh()}catch(e){setError(readError(e,'No fue posible eliminar la empresa'))}finally{setBusy('')}}
  const invite=async(b:PlatformBusiness)=>{const email=prompt('Correo del administrador de esta empresa:');if(!email)return;const name=prompt('Nombre del administrador (opcional):')??'';setBusy(b.id);setError('');try{const result=await resendPlatformInvitation(b.id,email,name);await refresh();alert(result.mode==='password'?`Ya existia una cuenta para ${email}. Envie un enlace para definir o recuperar contrasena.`:`Invitacion enviada a ${email}. Debe abrir el correo y crear su contrasena.`)}catch(e){setError(readError(e,'No fue posible preparar la invitacion'))}finally{setBusy('')}}
  return <><div className="tenant-tools"><div className="search-box"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar empresa, razon social o nicho..."/></div><div className="tenant-legend"><span><i className="active"/>Activa</span><span><i className="pending"/>Pendiente</span><span><i className="suspended"/>Suspendida</span></div></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<section className="card tenant-table">{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Cargando empresas...</b></div>:<div className="table-scroll"><table><thead><tr><th>Empresa</th><th>Nicho</th><th>Plan</th><th>Uso</th><th>Ventas historicas</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{rows.map(b=><tr key={b.id}><td><div className="tenant-name"><span style={{background:b.primaryColor}}>{b.name.slice(0,2).toUpperCase()}</span><div><b>{b.name}</b><small>{b.legalName||b.slug}</small></div></div></td><td><span className="industry-chip">{industryLabels[b.industry]}</span></td><td><b>{planLabels[b.plan]}</b><small className="subline">{b.maxUsers} usuarios ? {b.maxBranches} sucursales</small></td><td><b>{b.users}/{b.maxUsers} usuarios</b><small className="subline">{b.branches}/{b.maxBranches} sucursales ? {b.products} productos</small></td><td><b>{money(b.salesTotal)}</b></td><td><span className={`tenant-status ${b.status}`}>{statusLabels[b.status]}</span></td><td><div className="tenant-actions"><button title="Editar empresa" disabled={busy===b.id} onClick={()=>setEditing(b)}><Pencil/></button>{b.status==='pending'&&<button title="Enviar invitacion" disabled={busy===b.id} onClick={()=>invite(b)}><Mail/></button>}{b.status==='active'?<button className="danger" title="Suspender" disabled={busy===b.id} onClick={()=>change(b,'suspended')}><Power/></button>:b.status==='suspended'?<button className="success" title="Reactivar" disabled={busy===b.id} onClick={()=>change(b,'active')}><CheckCircle2/></button>:null}<button className="danger" title="Eliminar empresa" disabled={busy===b.id} onClick={()=>remove(b)}><Trash2/></button></div></td></tr>)}</tbody></table>{rows.length===0&&<div className="empty-table"><Building2/><b>No se encontraron empresas</b></div>}</div>}</section>{editing&&<EditBusinessDialog business={editing} close={()=>setEditing(null)} saved={async()=>{setEditing(null);await refresh()}}/>}</>
}
function NewBusinessDialog({close,saved}:{close:()=>void;saved:()=>Promise<void>}){
 const [form,setForm]=useState({name:'',legalName:'',industry:'retail',adminEmail:'',adminName:'',plan:'starter',slogan:'',primaryColor:'#155b3d',accentColor:'#c9f45c'});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const set=(k:string,v:string)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{const result=await createPlatformBusiness(form);await saved();alert(result.emailResult.mode==='password'?`Empresa creada. ${form.adminEmail} ya tenia cuenta, envi? enlace para definir o recuperar contrasena.`:`Empresa creada e invitacion enviada a ${form.adminEmail}.`)}catch(err){setError(readError(err,'No fue posible crear la empresa'))}finally{setBusy(false)}}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="product-dialog tenant-dialog card" onSubmit={submit}><div className="dialog-head"><div><span className="eyebrow">NUEVO CLIENTE</span><h3>Crear empresa independiente</h3><p>Se creará con datos, inventario, usuarios y sucursales privados.</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid"><label>Nombre comercial<input required value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Ej. Farmacia Central"/></label><label>Razón social<input value={form.legalName} onChange={e=>set('legalName',e.target.value)} placeholder="Ej. Farmacia Central, S.A."/></label><label>Nicho<select value={form.industry} onChange={e=>set('industry',e.target.value)}>{Object.entries(industryLabels).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label><label>Plan<select value={form.plan} onChange={e=>set('plan',e.target.value)}><option value="starter">Inicial · 1 sucursal / 5 usuarios</option><option value="business">Negocios · 5 sucursales / 30 usuarios</option><option value="enterprise">Empresarial · hasta 100 sucursales</option></select></label><label>Administrador principal<input required value={form.adminName} onChange={e=>set('adminName',e.target.value)} placeholder="Nombre completo"/></label><label>Correo para activar la cuenta<input required type="email" value={form.adminEmail} onChange={e=>set('adminEmail',e.target.value)} placeholder="administrador@empresa.com"/></label><label className="full">Eslogan<input value={form.slogan} onChange={e=>set('slogan',e.target.value)} placeholder="Una frase para la empresa"/></label><label>Color principal<div className="color-field"><input type="color" value={form.primaryColor} onChange={e=>set('primaryColor',e.target.value)}/><input value={form.primaryColor} onChange={e=>set('primaryColor',e.target.value)}/></div></label><label>Color de acento<div className="color-field"><input type="color" value={form.accentColor} onChange={e=>set('accentColor',e.target.value)}/><input value={form.accentColor} onChange={e=>set('accentColor',e.target.value)}/></div></label></div><div className="tenant-security-note"><ShieldCheck/><span><b>Privacidad por diseño</b>Esta empresa no podrá ver información de MUNDO MEGA ni de otros clientes.</span></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Creando espacio privado…':'Crear empresa'}</button></div></form></div>
}

function EditBusinessDialog({business,close,saved}:{business:PlatformBusiness;close:()=>void;saved:()=>Promise<void>}){
 const [form,setForm]=useState({name:business.name,legalName:business.legalName,industry:business.industry,plan:business.plan,status:business.status,slogan:business.slogan,primaryColor:business.primaryColor,accentColor:business.accentColor});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const set=(k:string,v:string)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await updatePlatformBusiness(business.id,form);await saved()}catch(err){setError(readError(err,'No fue posible actualizar la empresa'))}finally{setBusy(false)}}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="product-dialog tenant-dialog card" onSubmit={submit}><div className="dialog-head"><div><span className="eyebrow">EDITAR EMPRESA</span><h3>{business.name}</h3><p>Actualiza datos comerciales, plan, estado e identidad visual.</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid"><label>Nombre comercial<input required value={form.name} onChange={e=>set('name',e.target.value)}/></label><label>Razon social<input value={form.legalName} onChange={e=>set('legalName',e.target.value)}/></label><label>Nicho<select value={form.industry} onChange={e=>set('industry',e.target.value)}>{Object.entries(industryLabels).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label><label>Plan<select value={form.plan} onChange={e=>set('plan',e.target.value)}><option value="starter">Inicial - 1 sucursal / 5 usuarios</option><option value="business">Negocios - 5 sucursales / 30 usuarios</option><option value="enterprise">Empresarial - hasta 100 sucursales</option></select></label><label>Estado<select value={form.status} onChange={e=>set('status',e.target.value)}><option value="pending">Pendiente</option><option value="active">Activa</option><option value="suspended">Suspendida</option></select></label><label>Eslogan<input value={form.slogan} onChange={e=>set('slogan',e.target.value)}/></label><label>Color principal<div className="color-field"><input type="color" value={form.primaryColor} onChange={e=>set('primaryColor',e.target.value)}/><input value={form.primaryColor} onChange={e=>set('primaryColor',e.target.value)}/></div></label><label>Color de acento<div className="color-field"><input type="color" value={form.accentColor} onChange={e=>set('accentColor',e.target.value)}/><input value={form.accentColor} onChange={e=>set('accentColor',e.target.value)}/></div></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando...':'Guardar cambios'}</button></div></form></div>
}
function AuthScreen(){
  const [mode,setMode]=useState<'login'|'signup'>('login'); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [name,setName]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [notice,setNotice]=useState('')
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');setNotice('');try{
    if(!supabase)throw new Error('Supabase no está configurado')
    if(mode==='login'){const {error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error}
    else{const {data,error}=await supabase.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin,data:{full_name:name}}});if(error)throw error;if(!data.session)setNotice('Cuenta activada. Revisa tu correo para confirmar el acceso.');}
  }catch(err){setError(err instanceof Error?translateAuthError(err.message):'No fue posible continuar')}finally{setBusy(false)}}
  const resend=async()=>{if(!supabase||!email){setError('Escribe primero tu correo electrónico.');return}setBusy(true);setError('');const {error}=await supabase.auth.resend({type:'signup',email,options:{emailRedirectTo:window.location.origin}});setBusy(false);if(error)setError(translateAuthError(error.message));else setNotice('Te enviamos un nuevo enlace. Usa el correo más reciente.')}
  return <main className="auth-page"><section className="auth-showcase"><div className="auth-brand"><div className="brand-mark"><Store/></div><b>Grupo Multimarkets S.A.</b></div><div className="auth-copy"><span>PLATAFORMA MULTIEMPRESA</span><h1>Vende.<br/>Crece.</h1><p className="brand-slogan">Cada empresa, su propio espacio.</p><div className="auth-benefits"><div><CheckCircle2/><span><b>Datos independientes</b><small>Ventas, inventario y clientes privados.</small></span></div><div><CheckCircle2/><span><b>Para diferentes nichos</b><small>Comercios, farmacias, ferreterías y más.</small></span></div><div><CheckCircle2/><span><b>Administración central</b><small>Control general sin mezclar operaciones.</small></span></div></div></div><div className="auth-quote">GRUPO MULTIMARKETS · Plataforma empresarial.</div></section><section className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><div className="auth-mobile-brand"><div className="brand-mark"><Store/></div><b>Grupo Multimarkets S.A.</b></div><span className="eyebrow">BIENVENIDO</span><h2>{mode==='login'?'Inicia sesión':'Activa tu cuenta'}</h2><p>{mode==='login'?'Ingresa a tu empresa o al panel general.':'Usa exactamente el correo que recibió la invitación.'}</p>{mode==='signup'&&<label>Tu nombre<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Ej. Ana López"/></label>}<label>Correo electrónico<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="nombre@empresa.com"/></label><label>Contraseña<input required type="password" minLength={8} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Mínimo 8 caracteres"/></label>{error&&<div className="auth-message error">{error}</div>}{notice&&<div className="auth-message notice">{notice}</div>}<button className="auth-submit" disabled={busy}>{busy?<><RefreshCw className="spin"/>Procesando…</>:mode==='login'?'Iniciar sesión':'Activar cuenta invitada'}</button><div className="auth-switch">{mode==='login'?'¿Recibiste una invitación?':'¿Ya activaste tu cuenta?'} <button type="button" onClick={()=>{setMode(mode==='login'?'signup':'login');setError('');setNotice('')}}>{mode==='login'?'Activar cuenta':'Iniciar sesión'}</button></div></form></section></main>
}
function PasswordSetup({done}:{done:()=>void}){
  const [password,setPassword]=useState('');const [confirm,setConfirm]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');if(password.length<8){setError('La contrasena debe tener al menos 8 caracteres.');return}if(password!==confirm){setError('Las contrasenas no coinciden.');return}setBusy(true);try{if(!supabase)throw new Error('Supabase no esta configurado');const {error}=await supabase.auth.updateUser({password});if(error)throw error;done()}catch(err){setError(err instanceof Error?translateAuthError(err.message):'No fue posible guardar la contrasena')}finally{setBusy(false)}}
  return <main className="auth-page"><section className="auth-showcase"><div className="auth-brand"><div className="brand-mark"><Store/></div><b>Grupo Multimarkets S.A.</b></div><div className="auth-copy"><span>INVITACION ACEPTADA</span><h1>Define tu<br/>contrasena.</h1><p className="brand-slogan">Tu espacio privado ya est? casi listo.</p></div><div className="auth-quote">MUNDO MEGA ? Acceso seguro.</div></section><section className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><span className="eyebrow">ULTIMO PASO</span><h2>Crea tu contrasena</h2><p>La usar?s para entrar al sistema desde ahora.</p><label>Nueva contrasena<input required type="password" minLength={8} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Minimo 8 caracteres"/></label><label>Confirmar contrasena<input required type="password" minLength={8} value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="Repite la contrasena"/></label>{error&&<div className="auth-message error">{error}</div>}<button className="auth-submit" disabled={busy}>{busy?<><RefreshCw className="spin"/>Guardando...</>:'Guardar y entrar'}</button></form></section></main>
}
function translateAuthError(message:string){if(message.includes('Invalid login'))return 'Correo o contraseña incorrectos.';if(message.includes('already registered'))return 'Este correo ya está registrado.';if(message.includes('Password'))return 'La contraseña debe tener al menos 8 caracteres.';return message}
function readError(error:unknown,fallback:string){if(error instanceof Error)return error.message;if(error&&typeof error==='object'&&'message' in error)return String((error as {message?:unknown}).message||fallback);return fallback}

function BranchSwitcher({profile,refresh}:{profile:StoreProfile|null;refresh:()=>Promise<void>}){const [open,setOpen]=useState(false);const [rows,setRows]=useState<Branch[]>([]);const toggle=async()=>{if(!profile||!['admin','supervisor'].includes(profile.role))return;const next=!open;setOpen(next);if(next)setRows((await loadBranches(profile)).filter(b=>b.active))};const choose=async(id:string)=>{await switchBranch(id);await refresh();setOpen(false)};return <div className="branch-switch-wrap"><button className="branch" onClick={toggle}><span className="branch-icon">{profile?.businessName?.[0]??'M'}</span><div><small>{profile?.branchName??'Sucursal actual'}</small><strong>{profile?.businessName??'Cargando negocio…'}</strong></div>{['admin','supervisor'].includes(profile?.role??'')&&<ChevronDown size={16}/>}</button>{open&&<div className="branch-menu"><span>Cambiar de sucursal</span>{rows.map(b=><button className={b.id===profile?.branchId?'active':''} key={b.id} onClick={()=>choose(b.id)}><Store/><div><b>{b.name}</b><small>{b.address||'Sin dirección'}</small></div>{b.id===profile?.branchId&&<CheckCircle2/>}</button>)}</div>}</div>}

function Topbar({title,openMenu}:{title:string,openMenu:()=>void}){return <header className="topbar"><button className="menu-btn" onClick={openMenu}><Menu/></button><div><h1>{title}</h1><p>{title==='Resumen'?'MUNDO MEGA · Minimarket más cercano':'Grupo Multimarkets S.A.'}</p></div><div className="top-actions"><div className="search-global"><Search size={18}/><input placeholder="Buscar en el sistema..."/><kbd>⌘ K</kbd></div><button className="icon-btn notification"><Bell size={20}/><i/></button><div className="status-dot"><span/>Caja abierta</div></div></header>}

const chartData=[{h:'7am',v:180},{h:'8am',v:260},{h:'9am',v:410},{h:'10am',v:690},{h:'11am',v:520},{h:'12pm',v:840},{h:'1pm',v:650},{h:'2pm',v:1020},{h:'3pm',v:880},{h:'4pm',v:1240},{h:'5pm',v:1150},{h:'6pm',v:1480}]
function Dashboard({go,profile,catalog}:{go:(p:Page)=>void;profile:StoreProfile|null;catalog:Product[]}){const [liveSales,setLiveSales]=useState<LiveSale[]>([]);const refreshSales=async()=>{if(profile)setLiveSales(await loadSales(profile))};useEffect(()=>{refreshSales()},[profile]);const today=liveSales.filter(s=>new Date(s.date).toDateString()===new Date().toDateString()&&s.status==='completed');const revenue=today.reduce((s,x)=>s+x.total,0);const profit=today.reduce((s,x)=>s+x.total-x.cost,0);const hourly=Array.from({length:12},(_,i)=>{const hour=i+7;return {h:`${hour>12?hour-12:hour}${hour>=12?'pm':'am'}`,v:today.filter(s=>new Date(s.date).getHours()===hour).reduce((n,s)=>n+s.total,0)}});return <>
  <div className="welcome"><div><h2>Buenos días, Ana <span>👋</span></h2><p>Todo marcha bien. Aquí tienes el pulso de tu negocio.</p></div><button className="primary" onClick={()=>go('Punto de venta')}><ShoppingCart size={18}/>Nueva venta</button></div>
  <div className="metric-grid"><Metric label="Ventas de hoy" value={money(revenue)} change="Datos reales" up icon={CircleDollarSign}/><Metric label="Transacciones" value={String(today.length)} change="Completadas" up icon={ReceiptText}/><Metric label="Ticket promedio" value={money(today.length?revenue/today.length:0)} change="Promedio" up icon={ShoppingBag}/><Metric label="Ganancia estimada" value={money(profit)} change="Venta − costo" up={profit>=0} icon={BarChart3}/></div>
  <div className="dashboard-grid"><section className="card sales-chart"><CardHead title="Ventas de hoy" sub="Ingresos por hora" action={<button className="select-small">Hoy <ChevronDown size={14}/></button>}/><div className="chart-total"><strong>Q 4,286.50</strong><span><ArrowUpRight size={15}/>12.5% vs. ayer</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData}><defs><linearGradient id="salesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#39a96b" stopOpacity={.28}/><stop offset="100%" stopColor="#39a96b" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#eceeea"/><XAxis dataKey="h" axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#849087'}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#849087'}} tickFormatter={v=>`Q${v}`}/><Tooltip formatter={(v)=>money(Number(v))}/><Area type="monotone" dataKey="v" stroke="#278d57" strokeWidth={3} fill="url(#salesFill)"/></AreaChart></ResponsiveContainer></div></section>
    <section className="card low-stock"><CardHead title="Stock por agotarse" sub="Requieren atención" action={<button className="link-btn" onClick={()=>go('Productos')}>Ver inventario</button>}/>{catalog.filter(p=>p.stock<=p.minStock).length===0?<div className="empty-compact"><CheckCircle2/>Inventario saludable</div>:catalog.filter(p=>p.stock<=p.minStock).slice(0,4).map(p=><div className="stock-row" key={p.id}><ProductThumb p={p}/><div className="stock-info"><strong>{p.name}</strong><span>{p.sku} · {p.unit}</span><div className="progress"><i style={{width:`${Math.min(100,p.stock/Math.max(1,p.minStock)*100)}%`}}/></div></div><div className="stock-count"><b>{p.stock}</b><span>en stock</span></div></div>)}</section>
  </div>
  <section className="card recent"><CardHead title="Ventas recientes" sub="Últimas transacciones del día" action={<button className="link-btn">Ver todas <ArrowUpRight size={15}/></button>}/><SalesTable live={liveSales.slice(0,8)} profile={profile} onChanged={refreshSales}/></section>
  </>}
function Metric({label,value,change,up,icon:Icon}:{label:string,value:string,change:string,up:boolean,icon:any}){return <div className="metric card"><div className="metric-top"><span>{label}</span><div className="metric-icon"><Icon size={20}/></div></div><strong>{value}</strong><p className={up?'positive':'negative'}>{up?<ArrowUpRight/>:<ArrowDownRight/>}{change}<span> vs. ayer</span></p></div>}
function CardHead({title,sub,action}:{title:string,sub?:string,action?:any}){return <div className="card-head"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div>{action}</div>}

function ControlHub({profile,refreshStore,view}:{profile:StoreProfile|null;refreshStore:()=>Promise<void>;view?:CorporateView}){
  const [internalSection,setInternalSection]=useState<CorporateView>('overview');const section=view??internalSection
  if(!profile)return null
  const items:{id:CorporateView;label:string;Icon:any}[]=[
    {id:'overview',label:'Vista general',Icon:LayoutDashboard},{id:'movements',label:'Movimientos',Icon:RefreshCw},{id:'cashClosures',label:'Cierres de caja',Icon:ReceiptText},{id:'inventory',label:'Inventario global',Icon:Boxes},{id:'attendance',label:'Asistencia',Icon:CalendarDays},
    ...(profile.role==='admin'?[{id:'branches' as const,label:'Sucursales',Icon:Store},{id:'team' as const,label:'Usuarios',Icon:Users}]:[])
  ]
  return <div className="control-hub"><div className="hub-header"><div><span>CENTRO CORPORATIVO</span><h2>{profile.businessName}</h2><p>Administración y supervisión de todas las tiendas.</p></div><div className="hub-user"><div className="avatar">{profile.fullName.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><div><b>{profile.fullName}</b><small>{profile.role==='admin'?'Administrador central':'Supervisor corporativo'}</small></div></div></div>{!view&&<nav className="hub-nav">{items.map(({id,label,Icon})=><button className={section===id?'active':''} key={id} onClick={()=>setInternalSection(id)}><Icon/>{label}</button>)}</nav>}<div className="hub-content">{section==='overview'&&<ControlCenter profile={profile}/>} {section==='movements'&&<ControlMovements profile={profile}/>} {section==='cashClosures'&&<CashClosureReports profile={profile}/>} {section==='inventory'&&<ControlInventoryMatrix/>} {section==='attendance'&&<AttendanceControl profile={profile}/>} {section==='branches'&&profile.role==='admin'&&<BranchSettings profile={profile} refreshStore={refreshStore}/>} {section==='team'&&profile.role==='admin'&&<TeamSettings profile={profile}/>}</div></div>
}

const attendanceKindLabel=(kind:string)=>({start_shift:'Inicio de jornada',lunch_out:'Ir a comer',lunch_in:'Regresando de comer',end_shift:'Terminar dia',custom:'Personalizada'}[kind]??kind)
async function saveAttendanceEmployee(id:string,changes:{fullName?:string;position?:string;baseSalary?:number;branchId?:string|null;active?:boolean}){if(!supabase)throw new Error('Supabase no está configurado');const payload:any={};if(changes.fullName!==undefined)payload.full_name=changes.fullName;if(changes.position!==undefined)payload.position=changes.position||null;if(changes.baseSalary!==undefined)payload.base_salary=changes.baseSalary;if(changes.branchId!==undefined)payload.branch_id=changes.branchId||null;if(changes.active!==undefined)payload.active=changes.active;const {error}=await supabase.from('attendance_employees').update(payload).eq('id',id);if(error)throw error}
async function deleteAttendanceEmployee(id:string){if(!supabase)throw new Error('Supabase no está configurado');const {error}=await supabase.from('attendance_employees').delete().eq('id',id);if(error)throw error}
async function deleteAttendanceEvent(id:string){if(!supabase)throw new Error('Supabase no está configurado');const {error}=await supabase.from('attendance_events').delete().eq('id',id);if(error)throw error}
async function deleteAttendanceCategory(id:string){if(!supabase)throw new Error('Supabase no está configurado');const events=await supabase.from('attendance_events').delete().eq('category_id',id);if(events.error)throw events.error;const category=await supabase.from('attendance_categories').delete().eq('id',id);if(category.error)throw category.error}
async function saveAttendanceCategory(id:string,changes:{name?:string;kind?:string;active?:boolean}){if(!supabase)throw new Error('Supabase no está configurado');const payload:any={};if(changes.name!==undefined)payload.name=changes.name;if(changes.kind!==undefined)payload.kind=changes.kind;if(changes.active!==undefined)payload.active=changes.active;const {error}=await supabase.from('attendance_categories').update(payload).eq('id',id);if(error)throw error}

function AttendanceControl({profile}:{profile:StoreProfile}){const [employees,setEmployees]=useState<AttendanceEmployee[]>([]);const [categories,setCategories]=useState<AttendanceCategory[]>([]);const [events,setEvents]=useState<AttendanceEvent[]>([]);const [branches,setBranches]=useState<Branch[]>([]);const [period,setPeriod]=useState<'first'|'second'|'month'>(defaultAttendancePeriod());const [workRule,setWorkRule]=useState<'withSunday'|'withoutSunday'>('withoutSunday');const [branch,setBranch]=useState(profile.branchId);const [qrBranch,setQrBranch]=useState(profile.branchId);const [tab,setTab]=useState<'qr'|'employees'|'attendance'|'payroll'>('attendance');const [token,setToken]=useState('');const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [employeeOpen,setEmployeeOpen]=useState(false);const [categoryOpen,setCategoryOpen]=useState(false);const [editingEmployee,setEditingEmployee]=useState<AttendanceEmployee|null>(null);const [editingCategory,setEditingCategory]=useState<AttendanceCategory|null>(null);const range=useMemo(()=>attendanceRange(period),[period]);const refresh=async()=>{setLoading(true);setError('');try{const [data,k,b]=await Promise.all([loadAttendanceAdmin(profile,range.from,range.to),ensureAttendanceKiosk(qrBranch),loadBranches(profile)]);setEmployees(data.employees);setCategories(data.categories);setEvents(data.events);setToken(k);setBranches(b)}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar asistencia')}finally{setLoading(false)}};useEffect(()=>{refresh()},[period,qrBranch]);const link=token?`${window.location.origin}/?attendance=${token}`:'';const visibleEmployees=employees.filter(e=>e.active&&(!branch||e.branchId===branch));const visibleEvents=events.filter(e=>!branch||e.branchName===(branches.find(b=>b.id===branch)?.name??e.branchName));const payroll=visibleEmployees.map(e=>attendancePayroll(e,visibleEvents.filter(ev=>ev.employeeId===e.id),range,workRule));const totals=payroll.reduce((a,r)=>({earned:a.earned+r.earned,days:a.days+r.presentDays}),{earned:0,days:0});const removeEmployee=async(e:AttendanceEmployee)=>{if(!window.confirm(`¿Eliminar permanentemente a ${e.fullName}? También se borrarán sus marcajes de asistencia y no se podrá recuperar.`))return;await deleteAttendanceEmployee(e.id);await refresh()};const removeCategory=async(c:AttendanceCategory)=>{if(!window.confirm(`¿Eliminar permanentemente la categoría "${c.name}"? También se borrarán los marcajes registrados con esta categoría y no se podrá recuperar.`))return;await deleteAttendanceCategory(c.id);await refresh()};const removeEvent=async(e:AttendanceEvent)=>{if(!window.confirm(`�Eliminar este registro de asistencia de ${e.employeeName}? No se podr� recuperar.`))return;await deleteAttendanceEvent(e.id);await refresh()};return <><div className="hub-section-head"><div><h3>Asistencia y salarios</h3><p>QR compartido por sucursal, medio turno y salarios con regla de domingos.</p></div><div className="control-actions"><button className="secondary" onClick={()=>printAttendanceReport(profile,visibleEvents,visibleEmployees,range)}><Download/>Imprimir asistencia</button><button className="primary" onClick={()=>printPayrollReport(profile,payroll,range,workRule)}><ReceiptText/>Imprimir salarios</button></div></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<div className="inventory-control-stats"><MiniStat label="Empleados" value={String(visibleEmployees.length)} icon={Users}/><MiniStat label="Marcajes" value={String(visibleEvents.length)} icon={CalendarDays}/><MiniStat label="Dias pagables" value={String(totals.days)} icon={CheckCircle2}/><MiniStat label="Salarios calculados" value={money(totals.earned)} icon={CircleDollarSign}/></div><div className="movement-filters card"><select value={period} onChange={e=>setPeriod(e.target.value as any)}><option value="first">Primera quincena</option><option value="second">Segunda quincena</option><option value="month">Mes completo</option></select><select value={workRule} onChange={e=>setWorkRule(e.target.value as any)}><option value="withoutSunday">No trabaja domingos</option><option value="withSunday">Incluye domingos</option></select><select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><button className="secondary" onClick={refresh}><RefreshCw className={loading?'spin':''}/>Actualizar</button></div><div className="hub-nav"><button className={tab==='qr'?'active':''} onClick={()=>setTab('qr')}><CalendarDays/>QR</button><button className={tab==='employees'?'active':''} onClick={()=>setTab('employees')}><Users/>Empleados</button><button className={tab==='attendance'?'active':''} onClick={()=>setTab('attendance')}><Eye/>Asistencia</button><button className={tab==='payroll'?'active':''} onClick={()=>setTab('payroll')}><CircleDollarSign/>Salarios</button></div>{tab==='qr'&&<section className="card attendance-kiosk-card"><div><h3>QR general por sucursal</h3><p>Un solo QR para todos los empleados de la sucursal seleccionada. No es un QR por empleado.</p><select value={qrBranch} onChange={e=>setQrBranch(e.target.value)}>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><input readOnly value={link}/><div className="dialog-actions"><button className="secondary" onClick={()=>navigator.clipboard?.writeText(link)}>Copiar link</button><button className="primary" onClick={()=>window.open(link,'_blank')}>Abrir marcador</button></div></div>{link&&<img alt="QR asistencia" src={`https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(link)}`}/>}</section>}{tab==='employees'&&<><section className="card movement-table"><CardHead title="Empleados de asistencia" sub="Imprime asistencia o salario individual desde aqui" action={<div><button className="secondary" onClick={()=>setCategoryOpen(true)}><Plus/>Categoria</button><button className="primary" onClick={()=>setEmployeeOpen(true)}><Plus/>Empleado</button></div>}/><div className="table-scroll"><table><thead><tr><th>Empleado</th><th>Puesto</th><th>Sucursal</th><th>Base quincenal</th><th>Estado</th><th>Imprimir</th><th>Acciones</th></tr></thead><tbody>{employees.map(e=>{const empEvents=events.filter(ev=>ev.employeeId===e.id);const empPayroll=attendancePayroll(e,empEvents,range,workRule);return <tr key={e.id}><td><b>{e.fullName}</b></td><td>{e.position||'Colaborador'}</td><td>{e.branchName}</td><td>{money(e.baseSalary)}</td><td><span className={e.active?'badge success':'badge neutral'}>{e.active?'Activo':'Inactivo'}</span></td><td><div className="tenant-actions"><button title="Imprimir asistencia" onClick={()=>printAttendanceReport(profile,empEvents,[e],range)}><CalendarDays/></button><button title="Imprimir salario" onClick={()=>printPayrollReport(profile,[empPayroll],range,workRule)}><ReceiptText/></button></div></td><td><div className="tenant-actions"><button title="Editar empleado" onClick={()=>setEditingEmployee(e)}><Pencil/></button><button title={e.active?'Eliminar empleado':'Activar empleado'} onClick={()=>e.active?removeEmployee(e):updateAttendanceEmployee(e.id,{active:true}).then(refresh)}>{e.active?<Trash2/>:<Power/>}</button></div></td></tr>})}</tbody></table></div></section><section className="card movement-table"><CardHead title="Categorías de entrada y salida" sub="Edita las opciones que el empleado verá al escanear el QR"/><div className="table-scroll"><table><thead><tr><th>Categoría</th><th>Tipo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{categories.map(c=><tr key={c.id}><td><b>{c.name}</b></td><td>{attendanceKindLabel(c.kind)}</td><td><span className={c.active?'badge success':'badge neutral'}>{c.active?'Activa':'Inactiva'}</span></td><td><div className="tenant-actions"><button title="Editar categoría" onClick={()=>setEditingCategory(c)}><Pencil/></button><button title="Eliminar categoría permanentemente" onClick={()=>removeCategory(c)}><Trash2/></button></div></td></tr>)}</tbody></table></div></section></>}{tab==='attendance'&&<section className="card movement-table"><CardHead title="Reporte de asistencia" sub="Filtrado por periodo y sucursal"/><div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Empleado</th><th>Categoria</th><th>Sucursal</th><th>Nota</th><th>Acciones</th></tr></thead><tbody>{visibleEvents.slice(0,120).map(e=><tr key={e.id}><td>{new Date(e.markedAt).toLocaleString('es-GT')}</td><td><b>{e.employeeName}</b></td><td>{e.categoryName}</td><td>{e.branchName}</td><td>{e.note}</td><td><div className="tenant-actions"><button title="Eliminar registro" onClick={()=>removeEvent(e)}><Trash2/></button></div></td></tr>)}</tbody></table>{visibleEvents.length===0&&<div className="empty-table"><CalendarDays/><b>Sin marcajes en este periodo</b></div>}</div></section>}{tab==='payroll'&&<section className="card movement-table"><CardHead title="Control quincenal de salarios" sub={`${range.from.toLocaleDateString('es-GT')} al ${range.to.toLocaleDateString('es-GT')} - ${workRule==='withoutSunday'?'sin domingos':'con domingos'}`}/><div className="table-scroll"><table><thead><tr><th>Empleado</th><th>Puesto</th><th>Dias pagables</th><th>Base quincenal</th><th>Pago segun asistencia</th><th>Estado</th></tr></thead><tbody>{payroll.map(r=><tr key={r.employee.id}><td><b>{r.employee.fullName}</b><span className="subline">{r.employee.branchName}</span></td><td>{r.employee.position||'Colaborador'}</td><td>{r.presentDays}/{r.workingDays}</td><td>{money(r.baseSalary)}</td><td><b>{money(r.earned)}</b></td><td><span className={r.presentDays>=r.workingDays?'badge success':'badge warning'}>{r.presentDays>=r.workingDays?'Completo':'Parcial'}</span></td></tr>)}</tbody></table>{payroll.length===0&&<div className="empty-table"><Users/><b>Agrega empleados para calcular asistencia</b></div>}</div></section>}{employeeOpen&&<AttendanceEmployeeDialog profile={profile} branches={branches} close={()=>setEmployeeOpen(false)} saved={async()=>{setEmployeeOpen(false);await refresh()}}/>}{editingEmployee&&<AttendanceEmployeeDialog profile={profile} branches={branches} employee={editingEmployee} close={()=>setEditingEmployee(null)} saved={async()=>{setEditingEmployee(null);await refresh()}}/>}{categoryOpen&&<AttendanceCategoryDialog profile={profile} close={()=>setCategoryOpen(false)} saved={async()=>{setCategoryOpen(false);await refresh()}}/>}{editingCategory&&<AttendanceCategoryDialog profile={profile} category={editingCategory} close={()=>setEditingCategory(null)} saved={async()=>{setEditingCategory(null);await refresh()}}/>}</>}

function AttendanceEmployeeDialog({profile,branches,employee,close,saved}:{profile:StoreProfile;branches:Branch[];employee?:AttendanceEmployee;close:()=>void;saved:()=>Promise<void>}){const [form,setForm]=useState({fullName:employee?.fullName??'',position:employee?.position??'',baseSalary:String(employee?.baseSalary??750),branchId:employee?.branchId??profile.branchId});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{if(employee){await saveAttendanceEmployee(employee.id,{fullName:form.fullName,position:form.position,baseSalary:Number(form.baseSalary),branchId:form.branchId})}else{await createAttendanceEmployee(profile,{...form,baseSalary:Number(form.baseSalary)})}await saved()}catch(err){setError(err instanceof Error?err.message:employee?'No fue posible editar empleado':'No fue posible crear empleado')}finally{setBusy(false)}};return <div className="modal-backdrop"><form className="product-dialog small-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>{employee?'Editar empleado':'Nuevo empleado'}</h3><p>{employee?'Actualiza nombre, puesto, sucursal o salario base.':'No necesita usuario del sistema para marcar asistencia.'}</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid one"><label>Nombre completo<input required value={form.fullName} onChange={e=>setForm({...form,fullName:e.target.value})}/></label><label>Puesto o categoria<input value={form.position} onChange={e=>setForm({...form,position:e.target.value})}/></label><label>Base quincenal (Q)<input required type="number" step="0.01" value={form.baseSalary} onChange={e=>setForm({...form,baseSalary:e.target.value})}/></label><label>Sucursal<select value={form.branchId??''} onChange={e=>setForm({...form,branchId:e.target.value})}>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando...':employee?'Guardar cambios':'Crear empleado'}</button></div></form></div>}

function AttendanceCategoryDialog({profile,category,close,saved}:{profile:StoreProfile;category?:AttendanceCategory;close:()=>void;saved:()=>Promise<void>}){const [name,setName]=useState(category?.name??'');const [kind,setKind]=useState<string>(category?.kind??'custom');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{if(category){await saveAttendanceCategory(category.id,{name,kind})}else{await createAttendanceCategory(profile,{name,kind})}await saved()}catch(err){setError(err instanceof Error?err.message:category?'No fue posible editar categoria':'No fue posible crear categoria')}finally{setBusy(false)}};return <div className="modal-backdrop"><form className="product-dialog small-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>{category?'Editar categoria':'Nueva categoria'}</h3><p>Ej. Inicio de turno nocturno, salida especial, permiso.</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid one"><label>Nombre<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>Tipo<select value={kind} onChange={e=>setKind(e.target.value)}><option value="start_shift">Inicio de jornada</option><option value="lunch_out">Ir a comer</option><option value="lunch_in">Regresando de comer</option><option value="end_shift">Terminar dia</option><option value="custom">Personalizada</option></select></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando...':category?'Guardar cambios':'Crear categoria'}</button></div></form></div>}

function AttendanceKiosk({token}:{token:string}){const [data,setData]=useState<any>(null);const [employee,setEmployee]=useState('');const [category,setCategory]=useState('');const [note,setNote]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');useEffect(()=>{getAttendanceKioskData(token).then(d=>{setData(d);setEmployee(d.employees?.[0]?.id??'');setCategory(d.categories?.[0]?.id??'')}).catch(e=>setError(e instanceof Error?e.message:'Link no valido'))},[token]);const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');setMessage('');try{const r=await markAttendance(token,employee,category,note);setMessage(`${r.employeeName} - ${r.categoryName} registrado a las ${new Date(r.markedAt).toLocaleTimeString('es-GT')}`);setNote('')}catch(err){setError(err instanceof Error?err.message:'No fue posible registrar')}finally{setBusy(false)}};if(!data&&!error)return <div className="app-loading"><div className="brand-mark"><CalendarDays/></div><span>Cargando marcador...</span></div>;return <main className="auth-page"><section className="auth-showcase"><div className="auth-brand"><div className="brand-mark"><CalendarDays/></div><b>{data?.business?.name??'Asistencia'}</b></div><div className="auth-copy"><span>CONTROL DE ASISTENCIA</span><h1>Marca tu<br/>jornada.</h1><p className="brand-slogan">La hora se guarda automaticamente.</p></div><div className="auth-quote">{data?.branch?.name??'Marcaje general'}</div></section><section className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><span className="eyebrow">MARCAJE QR</span><h2>Selecciona tu asistencia</h2><p>Si trabajaste medio dia o no marcaste almuerzo, igual puedes seleccionar Terminar dia.</p>{error&&<div className="auth-message error">{error}</div>}{data&&<><label>Empleado<select value={employee} onChange={e=>setEmployee(e.target.value)}>{data.employees.map((e:any)=><option key={e.id} value={e.id}>{e.fullName}</option>)}</select></label><label>Categoria<select value={category} onChange={e=>setCategory(e.target.value)}>{data.categories.map((c:any)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Nota opcional<input value={note} onChange={e=>setNote(e.target.value)} placeholder="Ej. turno noche, permiso, medio dia"/></label>{message&&<div className="auth-message notice">{message}</div>}<button className="auth-submit" disabled={busy||!employee||!category}>{busy?<><RefreshCw className="spin"/>Registrando...</>:'Registrar asistencia'}</button></>}</form></section></main>}

function defaultAttendancePeriod():'first'|'second'{return new Date().getDate()<=15?'first':'second'}
function attendanceRange(period:'first'|'second'|'month'){const now=new Date();const from=new Date(now.getFullYear(),now.getMonth(),period==='second'?16:1);const to=period==='first'?new Date(now.getFullYear(),now.getMonth(),15,23,59,59):new Date(now.getFullYear(),now.getMonth()+1,0,23,59,59);return {from,to,label:period==='first'?'Primera quincena':period==='second'?'Segunda quincena':'Mes completo'}}
function attendanceWorkDays(range:{from:Date;to:Date},rule:'withSunday'|'withoutSunday'){let n=0;const d=new Date(range.from);d.setHours(12,0,0,0);const end=new Date(range.to);end.setHours(12,0,0,0);while(d<=end){if(rule==='withSunday'||d.getDay()!==0)n++;d.setDate(d.getDate()+1)}return Math.max(1,n)}
function isHalfShiftEvent(e:AttendanceEvent){const x=(e.categoryName+' '+e.categoryKind).toLowerCase();return x.includes('medio turno')||x.includes('medio dia')||x.includes('medio día')||x.includes('half')}
function attendancePayroll(employee:AttendanceEmployee,events:AttendanceEvent[],range:{from:Date;to:Date},rule:'withSunday'|'withoutSunday'='withoutSunday'){const byDay=new Map<string,AttendanceEvent[]>();events.forEach(e=>{const d=new Date(e.markedAt);if(rule==='withoutSunday'&&d.getDay()===0)return;const key=d.toDateString();byDay.set(key,[...(byDay.get(key)??[]),e])});const units=Array.from(byDay.values()).reduce((n,day)=>n+(day.some(isHalfShiftEvent)?0.5:1),0);const workingDays=attendanceWorkDays(range,rule);const earned=employee.baseSalary*Math.min(units,workingDays)/workingDays;return {employee,presentDays:units,workingDays,baseSalary:employee.baseSalary,earned}}
function printAttendanceReport(profile:StoreProfile,events:AttendanceEvent[],employees:AttendanceEmployee[],range:{from:Date;to:Date;label:string}){const rows=events.slice().reverse().map(e=>`<tr><td>${new Date(e.markedAt).toLocaleString('es-GT')}</td><td>${e.employeeName}</td><td>${e.categoryName}</td><td>${e.branchName}</td><td>${e.note}</td></tr>`).join('');printHtml('Control de asistencia',`<h1>${profile.businessName} / control de asistencia</h1><p>${range.label}: ${range.from.toLocaleDateString('es-GT')} al ${range.to.toLocaleDateString('es-GT')}</p><table><thead><tr><th>Fecha</th><th>Empleado</th><th>Categoria</th><th>Sucursal</th><th>Nota</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Sin marcajes</td></tr>'}</tbody></table>`)}
function printPayrollReport(profile:StoreProfile,rows:ReturnType<typeof attendancePayroll>[],range:{from:Date;to:Date;label:string},rule:'withSunday'|'withoutSunday'='withoutSunday'){const body=rows.map(r=>`<tr><td>${r.employee.fullName}</td><td>${r.presentDays}/${r.workingDays}</td><td>${money(r.baseSalary)}</td><td>${money(r.earned)}</td><td></td></tr>`).join('');const total=rows.reduce((n,r)=>n+r.earned,0);printHtml('Control de salarios',`<h1>GRUPO MULTIMARKETS S.A. ${profile.businessName} / cuadro de pago salarial</h1><p>QUINCENA: ${range.label} (${range.from.toLocaleDateString('es-GT')} - ${range.to.toLocaleDateString('es-GT')})</p><p>REGLA: ${rule==='withoutSunday'?'No se trabajan domingos':'Incluye domingos'}</p><table><thead><tr><th>Colaborador</th><th>Asistencia</th><th>Base quincenal</th><th>Total a recibir</th><th>Firma</th></tr></thead><tbody>${body}</tbody><tfoot><tr><td colspan="3"><b>TOTAL GENERAL</b></td><td><b>${money(total)}</b></td><td></td></tr></tfoot></table>`)}
function printHtml(title:string,body:string){const html=`<!doctype html><html><head><title>${title}</title><style>body{font-family:Georgia,serif;margin:18px;color:#000}h1{text-align:center;font-size:18px;text-transform:uppercase}table{width:100%;border-collapse:collapse}th,td{border:1px solid #111;padding:6px;font-size:13px}th{background:#f5f5f5}tfoot td{font-size:15px}@media print{button{display:none}}</style></head><body>${body}<br/><button onclick="window.print()">Imprimir</button><script>window.onload=function(){setTimeout(function(){window.print()},300)}</script></body></html>`;const w=window.open('','_blank','width=980,height=800');if(w){w.document.write(html);w.document.close()}}

function ControlMovements({profile}:{profile:StoreProfile}){const [rows,setRows]=useState<ControlMovement[]>([]);const [branches,setBranches]=useState<Branch[]>([]);const [branch,setBranch]=useState('');const [days,setDays]=useState('30');const [q,setQ]=useState('');const [loading,setLoading]=useState(true);const [error,setError]=useState('');const refresh=async()=>{setLoading(true);try{const to=new Date();const from=new Date();from.setDate(from.getDate()-Number(days));const [moves,b]=await Promise.all([loadControlMovements(from,to,branch||undefined),loadBranches(profile)]);setRows(moves);setBranches(b);setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar movimientos')}finally{setLoading(false)}};useEffect(()=>{refresh()},[branch,days]);const shown=rows.filter(r=>(r.description+' '+r.userName+' '+r.type).toLowerCase().includes(q.toLowerCase()));return <><div className="hub-section-head"><div><h3>Movimientos de todas las sucursales</h3><p>Ventas, compras, devoluciones, anulaciones e ingresos o retiros de caja.</p></div><button className="secondary" onClick={refresh}><RefreshCw/>Actualizar</button></div><div className="movement-filters card"><div className="search-box"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar movimiento o usuario..."/></div><select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select><select value={days} onChange={e=>setDays(e.target.value)}><option value="7">Últimos 7 días</option><option value="30">Últimos 30 días</option><option value="90">Últimos 90 días</option></select></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<section className="card movement-table">{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Cargando movimientos…</b></div>:<div className="table-scroll"><table><thead><tr><th>Fecha y hora</th><th>Sucursal</th><th>Tipo</th><th>Descripción</th><th>Usuario</th><th>Monto</th></tr></thead><tbody>{shown.map(r=><tr key={`${r.type}-${r.id}`}><td>{new Date(r.date).toLocaleString('es-GT')}</td><td><b>{r.branchName}</b></td><td><span className={`movement-type ${r.type.toLowerCase().replaceAll(' ','-')}`}>{r.type}</span></td><td>{r.description}</td><td>{r.userName}</td><td className={r.amount<0?'negative-text':'positive-text'}>{money(r.amount)}</td></tr>)}</tbody></table>{shown.length===0&&<div className="empty-table"><Search/><b>Sin movimientos para mostrar</b></div>}</div>}</section></>}

function CashClosureReports({profile}:{profile:StoreProfile}){const [rows,setRows]=useState<CashClosureReport[]>([]);const [branches,setBranches]=useState<Branch[]>([]);const [branch,setBranch]=useState('');const [days,setDays]=useState('7');const [selected,setSelected]=useState<CashClosureReport|null>(null);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const refresh=async()=>{setLoading(true);try{const to=new Date();const from=new Date();from.setDate(from.getDate()-Number(days));const [r,b]=await Promise.all([loadCashClosureReports(from,to,branch||undefined),loadBranches(profile)]);setRows(r);setBranches(b);setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar cierres de caja')}finally{setLoading(false)}};useEffect(()=>{refresh()},[branch,days]);const totals=rows.reduce((a,r)=>({sales:a.sales+r.totalSales,cash:a.cash+r.cashSales,diff:a.diff+r.difference,refunds:a.refunds+r.refunds}),{sales:0,cash:0,diff:0,refunds:0});return <><div className="hub-section-head"><div><h3>Reportes diarios de cierre de caja</h3><p>Revisa cada cierre por sucursal, cajero y diferencia de efectivo.</p></div><button className="secondary" onClick={refresh}><RefreshCw/>Actualizar</button></div><div className="inventory-control-stats"><MiniStat label="Cierres" value={String(rows.length)} icon={ReceiptText}/><MiniStat label="Ventas cerradas" value={money(totals.sales)} icon={CircleDollarSign}/><MiniStat label="Efectivo" value={money(totals.cash)} icon={Banknote}/><MiniStat label="Diferencia" value={money(totals.diff)} icon={AlertTriangle} warn={Math.abs(totals.diff)>0}/></div><div className="movement-filters card"><select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select><select value={days} onChange={e=>setDays(e.target.value)}><option value="1">Hoy / ultimas 24 horas</option><option value="7">Ultimos 7 dias</option><option value="30">Ultimos 30 dias</option><option value="90">Ultimos 90 dias</option></select></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<section className="card movement-table">{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Cargando cierres...</b></div>:<div className="table-scroll"><table><thead><tr><th>Cierre</th><th>Sucursal</th><th>Cajero</th><th>Ventas</th><th>Efectivo esperado</th><th>Contado</th><th>Diferencia</th><th>Acciones</th></tr></thead><tbody>{rows.map(r=><tr key={r.sessionId}><td>{new Date(r.closedAt).toLocaleString('es-GT')}</td><td><b>{r.branchName}</b><span className="subline">Apertura {new Date(r.openedAt).toLocaleString('es-GT')}</span></td><td>{r.userName}</td><td><b>{money(r.totalSales)}</b></td><td>{money(r.expectedAmount)}</td><td>{money(r.closingAmount)}</td><td className={Math.abs(r.difference)>0?'negative-text':'positive-text'}>{money(r.difference)}</td><td><button className="secondary" onClick={()=>setSelected(r)}><Eye/>Abrir</button></td></tr>)}</tbody></table>{rows.length===0&&<div className="empty-table"><ReceiptText/><b>No hay cierres en este periodo</b></div>}</div>}</section>{selected&&<CashClosureDetail report={selected} close={()=>setSelected(null)}/>}</>}
function CashClosureDetail({report,close}:{report:CashClosureReport;close:()=>void}){const [movements,setMovements]=useState(report.movements??[]);const [loading,setLoading]=useState(false);const [error,setError]=useState('');useEffect(()=>{let alive=true;setLoading(true);loadCashClosureMovements(report.sessionId).then(rows=>{if(alive)setMovements(rows)}).catch(e=>{if(alive)setError(e instanceof Error?e.message:'No fue posible cargar movimientos')}).finally(()=>{if(alive)setLoading(false)});return()=>{alive=false}},[report.sessionId]);const print=()=>printCashClosureReport({...report,movements});return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div className="product-dialog small-dialog card"><div className="dialog-head"><div><h3>Cierre de caja</h3><p>{report.branchName} ? {new Date(report.closedAt).toLocaleString('es-GT')}</p></div><button type="button" onClick={close}><X/></button></div><div className="cash-summary"><div><span>Responsable</span><b>{report.userName}</b></div><div><span>Fondo inicial</span><b>{money(report.openingAmount)}</b></div><div><span>Ventas efectivo</span><b>{money(report.cashSales)}</b></div><div><span>Ventas tarjeta</span><b>{money(report.cardSales)}</b></div><div><span>Transferencias</span><b>{money(report.transferSales)}</b></div><div><span>Devoluciones</span><b>{money(report.refunds)}</b></div><div><span>Ingresos manuales</span><b>{money(report.manualIncome)}</b></div><div><span>Retiros</span><b>{money(report.manualExpense)}</b></div><div><span>Movimientos</span><b>{loading?'Cargando...':String(movements.length)}</b></div><div><span>Esperado</span><b>{money(report.expectedAmount)}</b></div><div><span>Contado</span><b>{money(report.closingAmount)}</b></div><div><span>Diferencia</span><b className={Math.abs(report.difference)>0?'negative-text':'positive-text'}>{money(report.difference)}</b></div></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cerrar</button><button className="primary" disabled={loading} onClick={print}><ReceiptText/>Imprimir reporte</button></div></div></div>}
function ControlInventoryMatrix(){const [rows,setRows]=useState<ControlInventory[]>([]);const [q,setQ]=useState('');const [loading,setLoading]=useState(true);const [error,setError]=useState('');const refresh=async()=>{setLoading(true);try{setRows(await loadControlInventory());setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar inventario')}finally{setLoading(false)}};useEffect(()=>{refresh()},[]);const shown=rows.filter(r=>(r.productName+r.sku+r.category).toLowerCase().includes(q.toLowerCase()));const branchNames=Array.from(new Set(rows.flatMap(r=>Object.keys(r.stockByBranch)))).sort();const totalValue=rows.reduce((n,r)=>n+r.inventoryValue,0);return <><div className="hub-section-head"><div><h3>Inventario consolidado</h3><p>Existencias de cada producto en todas las sucursales.</p></div><button className="secondary" onClick={refresh}><RefreshCw/>Actualizar</button></div><div className="inventory-control-stats"><MiniStat label="Productos" value={String(rows.length)} icon={Package}/><MiniStat label="Valor total" value={money(totalValue)} icon={CircleDollarSign}/><MiniStat label="Sucursales" value={String(branchNames.length)} icon={Store}/></div><div className="search-box inventory-search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar producto, SKU o categoría..."/></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<section className="card inventory-matrix">{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Consolidando inventario…</b></div>:<div className="table-scroll"><table><thead><tr><th>Producto</th><th>Categoría</th>{branchNames.map(b=><th key={b}>{b}</th>)}<th>Total</th><th>Valor</th></tr></thead><tbody>{shown.map(r=><tr key={r.productId}><td><b>{r.productName}</b><span className="subline">{r.sku}</span></td><td><span className="category-tag">{r.category}</span></td>{branchNames.map(b=>{const stock=Number(r.stockByBranch[b]??0);return <td key={b}><span className={stock<=0?'stock-matrix empty':stock<=r.minStock?'stock-matrix low':'stock-matrix'}>{stock}</span></td>})}<td><b>{r.totalStock}</b></td><td>{money(r.inventoryValue)}</td></tr>)}</tbody></table></div>}</section></>}

function ControlCenter({profile}:{profile:StoreProfile|null}){const [period,setPeriod]=useState<'7'|'30'|'month'>('month');const [rows,setRows]=useState<BranchReport[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const range=useMemo(()=>{const to=new Date();const from=new Date();if(period==='7')from.setDate(from.getDate()-7);else if(period==='30')from.setDate(from.getDate()-30);else{from.setDate(1);from.setHours(0,0,0,0)}return {from,to}},[period]);const refresh=async()=>{if(!profile)return;setLoading(true);try{setRows(await loadBranchControl(range.from,range.to));setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar el reporte')}finally{setLoading(false)}};useEffect(()=>{refresh()},[profile,period]);const totals=rows.reduce((a,r)=>({sales:a.sales+r.netSales,refunds:a.refunds+r.refunds,profit:a.profit+r.grossProfit,tx:a.tx+r.transactions,inventory:a.inventory+r.inventoryValue}),{sales:0,refunds:0,profit:0,tx:0,inventory:0});const exportCsv=()=>{const header='Sucursal,Ventas netas,Devoluciones,Transacciones,Ticket promedio,Utilidad,Margen,Inventario,Stock bajo,Agotados';const body=rows.map(r=>[r.branchName,r.netSales,r.refunds,r.transactions,r.averageTicket,r.grossProfit,r.margin,r.inventoryValue,r.lowStock,r.outOfStock].join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([header+'\n'+body],{type:'text/csv'}));a.download=`reporte-sucursales-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)};return <><div className="page-intro control-intro"><div><h2>Centro de control</h2><p>Vista consolidada de todas las sucursales de {profile?.businessName}.</p></div><div className="control-actions"><div className="period-tabs">{[['7','7 días'],['30','30 días'],['month','Este mes']].map(([v,l])=><button className={period===v?'active':''} onClick={()=>setPeriod(v as any)} key={v}>{l}</button>)}</div><button className="secondary" onClick={exportCsv}><Download/>Exportar</button></div></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<div className="metric-grid"><Metric label="Ventas netas" value={money(totals.sales)} change="Todas las tiendas" up icon={CircleDollarSign}/><Metric label="Transacciones" value={String(totals.tx)} change="Consolidadas" up icon={ReceiptText}/><Metric label="Utilidad bruta" value={money(totals.profit)} change={`${totals.sales?((totals.profit/totals.sales)*100).toFixed(1):0}% margen`} up={totals.profit>=0} icon={BarChart3}/><Metric label="Valor de inventario" value={money(totals.inventory)} change="Todas las tiendas" up icon={Boxes}/></div><section className="card control-chart"><CardHead title="Comparativo de sucursales" sub="Ventas netas y utilidad bruta" action={<button className="icon-btn" onClick={refresh}><RefreshCw/></button>}/><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><BarChart data={rows} margin={{left:10,right:15}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#eceeea"/><XAxis dataKey="branchName" axisLine={false} tickLine={false} tick={{fontSize:10}}/><YAxis axisLine={false} tickLine={false} tickFormatter={v=>`Q${Math.round(v/1000)}k`}/><Tooltip formatter={(v)=>money(Number(v))}/><Bar dataKey="netSales" name="Ventas netas" fill="#278d57" radius={[5,5,0,0]}/><Bar dataKey="grossProfit" name="Utilidad" fill="#c9f45c" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></section><section className="card branch-matrix"><CardHead title="Matriz de rendimiento" sub={`${rows.length} sucursales · ${range.from.toLocaleDateString('es-GT')} al ${range.to.toLocaleDateString('es-GT')}`}/>{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Calculando resultados…</b></div>:<div className="table-scroll"><table><thead><tr><th>Sucursal</th><th>Ventas netas</th><th>Devoluciones</th><th>Transacciones</th><th>Ticket prom.</th><th>Utilidad</th><th>Margen</th><th>Inventario</th><th>Alertas</th></tr></thead><tbody>{rows.map((r,i)=><tr key={r.branchId}><td><div className="matrix-branch"><span>{i+1}</span><div><b>{r.branchName}</b><small>{r.active?'Activa':'Inactiva'}</small></div></div></td><td><b>{money(r.netSales)}</b></td><td className={r.refunds>0?'negative-text':''}>{money(r.refunds)}</td><td>{r.transactions}</td><td>{money(r.averageTicket)}</td><td className={r.grossProfit>=0?'positive-text':'negative-text'}>{money(r.grossProfit)}</td><td><span className={r.margin>=25?'margin good':r.margin>=10?'margin':'margin bad'}>{r.margin.toFixed(1)}%</span></td><td>{money(r.inventoryValue)}</td><td><div className="alert-counts"><span className={r.lowStock?'warn':''}>{r.lowStock} bajos</span><span className={r.outOfStock?'bad':''}>{r.outOfStock} agotados</span></div></td></tr>)}</tbody><tfoot><tr><td><b>TOTAL</b></td><td><b>{money(totals.sales)}</b></td><td>{money(totals.refunds)}</td><td><b>{totals.tx}</b></td><td>{money(totals.tx?totals.sales/totals.tx:0)}</td><td><b>{money(totals.profit)}</b></td><td>{totals.sales?((totals.profit/totals.sales)*100).toFixed(1):0}%</td><td><b>{money(totals.inventory)}</b></td><td/></tr></tfoot></table></div>}</section></>}

function POS({catalog,profile,refresh}:{catalog:Product[];profile:StoreProfile|null;refresh:()=>Promise<void>}){const [cart,setCart]=useState<CartItem[]>([]); const [query,setQuery]=useState(''); const [cat,setCat]=useState('Todos'); const [pay,setPay]=useState<'Efectivo'|'Tarjeta'|'Transferencia'>('Efectivo'); const [paid,setPaid]=useState(false); const [receipt,setReceipt]=useState<ReceiptData|null>(null); const [charging,setCharging]=useState(false); const [chargeError,setChargeError]=useState('')
 const filtered=catalog.filter(p=>(cat==='Todos'||p.category===cat)&&p.name.toLowerCase().includes(query.toLowerCase())); const subtotal=cart.reduce((s,p)=>s+p.price*p.quantity,0); const tax=0; const total=subtotal+tax
 const add=(p:Product)=>setCart(c=>{const found=c.find(i=>i.id===p.id);if((found?.quantity??0)>=p.stock)return c;return found?c.map(i=>i.id===p.id?{...i,quantity:i.quantity+1}:i):[...c,{...p,quantity:1}]}); const qty=(id:string,d:number)=>setCart(c=>c.map(i=>i.id===id?{...i,quantity:Math.max(1,Math.min(i.stock,i.quantity+d))}:i));
 const checkout=async()=>{if(!profile||!cart.length)return;setCharging(true);setChargeError('');try{const sale=await api.sales.checkout({businessId:profile.businessId,branchId:profile.branchId,cashierId:profile.id,items:cart.map(i=>({product_id:i.id,product_name:i.name,quantity:i.quantity,unit_cost:i.cost,unit_price:i.price,discount:0,tax:0,total:i.price*i.quantity})),payments:[{method:pay==='Efectivo'?'cash':pay==='Tarjeta'?'card':'transfer',amount:total}]});setReceipt({businessName:profile.businessName,taxId:profile.taxId,businessPhone:profile.businessPhone,branchName:profile.branchName,branchAddress:profile.branchAddress,branchPhone:profile.branchPhone,saleNumber:sale.number,cashier:profile.fullName,date:sale.created_at??new Date(),paymentMethod:pay,subtotal,discount:0,tax,total,lines:cart.map(i=>({name:i.name,quantity:i.quantity,unitPrice:i.price,total:i.price*i.quantity}))});await refresh();setPaid(true)}catch(e){setChargeError(e instanceof Error?e.message:'No fue posible completar la venta')}finally{setCharging(false)}}
 if(paid)return <div className="success-screen card"><div className="success-icon"><CheckCircle2 size={44}/></div><h2>¡Venta completada!</h2><p>La venta <b>#{String(receipt?.saleNumber??'').padStart(5,'0')}</b> fue registrada correctamente.</p><strong>{money(total)}</strong><label className="paper-choice">Papel <select defaultValue={localStorage.getItem('receipt-paper')||'80mm'} onChange={e=>localStorage.setItem('receipt-paper',e.target.value)}><option value="80mm">80 mm</option><option value="58mm">58 mm</option></select></label><div><button className="secondary" onClick={()=>receipt&&printThermalReceipt(receipt)}><ReceiptText size={18}/>Imprimir ticket</button><button className="primary" onClick={()=>{setPaid(false);setReceipt(null);setCart([])}}><Plus size={18}/>Nueva venta</button></div></div>
 return <div className="pos-layout"><section className="pos-products"><div className="pos-search"><Search/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar producto por nombre o código..."/><button><ScanBarcode size={20}/>Escanear</button></div><div className="category-chips">{['Todos','Bebidas','Granos','Lácteos','Snacks','Hogar'].map(c=><button key={c} className={cat===c?'active':''} onClick={()=>setCat(c)}>{c}</button>)}</div><div className="product-grid">{filtered.map(p=><button className="product-card" key={p.id} onClick={()=>add(p)}><ProductThumb p={p} big/><div className="product-copy"><strong>{p.name}</strong><span>{p.unit}</span><div><b>{money(p.price)}</b><em className={p.stock<=p.minStock?'low':''}>{p.stock} disp.</em></div></div><span className="add-product"><Plus size={18}/></span></button>)}</div></section>
 <aside className="cart-panel"><div className="cart-title"><div><h2>Venta actual</h2><span>{cart.reduce((s,i)=>s+i.quantity,0)} productos</span></div><button onClick={()=>setCart([])}><Trash2 size={18}/></button></div><button className="customer-select"><div><UserRound size={18}/><span><small>Cliente</small><b>Consumidor final</b></span></div><ChevronDown size={17}/></button><div className="cart-items">{cart.length===0?<div className="empty-cart"><ShoppingCart/><b>Tu carrito está vacío</b><span>Agrega productos para comenzar</span></div>:cart.map(i=><div className="cart-item" key={i.id}><ProductThumb p={i}/><div className="cart-item-main"><strong>{i.name}</strong><span>{money(i.price)} c/u</span><div className="stepper"><button onClick={()=>qty(i.id,-1)}><Minus/></button><b>{i.quantity}</b><button onClick={()=>qty(i.id,1)}><Plus/></button></div></div><div className="cart-item-price"><b>{money(i.price*i.quantity)}</b><button onClick={()=>setCart(c=>c.filter(x=>x.id!==i.id))}><X/></button></div></div>)}</div><div className="cart-bottom"><div className="totals"><p><span>Subtotal</span><b>{money(subtotal)}</b></p><p><span>Impuestos</span><b>{money(tax)}</b></p><p className="grand"><span>Total</span><b>{money(total)}</b></p></div><label className="payment-label">Método de pago</label><div className="pay-methods">{([['Efectivo',Banknote],['Tarjeta',CreditCard],['Transferencia',RefreshCw]] as const).map(([m,I])=><button className={pay===m?'active':''} onClick={()=>setPay(m)} key={m}><I/><span>{m}</span></button>)}</div>{chargeError&&<div className="auth-message error">{chargeError}</div>}<button className="charge" disabled={!cart.length||charging||!profile} onClick={checkout}><span>{charging?'Procesando…':'Cobrar'}</span><b>{money(total)}</b></button><p className="shortcut">Presiona <kbd>F2</kbd> para cobrar</p></div></aside></div>}

function Products({catalog,profile,refresh}:{catalog:Product[];profile:StoreProfile|null;refresh:()=>Promise<void>}){
  const [q,setQ]=useState(''); const [open,setOpen]=useState(false)
  const rows=catalog.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())||p.sku.toLowerCase().includes(q.toLowerCase()))
  const low=catalog.filter(p=>p.stock<=p.minStock).length
  return <><PageIntro title="Productos e inventario" text="Controla existencias, precios y movimientos de tus productos." button="Nuevo producto" onAction={()=>setOpen(true)}/><div className="inventory-stats"><MiniStat label="Productos activos" value={String(catalog.length)} icon={Package}/><MiniStat label="Valor del inventario" value={money(catalog.reduce((s,p)=>s+p.cost*p.stock,0))} icon={Boxes}/><MiniStat label="Stock bajo" value={`${low} productos`} icon={AlertTriangle} warn/><MiniStat label="Sin existencias" value={`${catalog.filter(p=>p.stock<=0).length} productos`} icon={X}/></div><section className="card table-card"><div className="table-tools"><div className="search-box"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar producto, SKU o código..."/></div><button className="secondary"><ListFilter/>Filtros</button><button className="secondary"><Download/>Exportar</button></div>{rows.length===0?<div className="empty-table"><Package/><b>Aún no hay productos</b><span>Crea tu primer producto para comenzar a vender.</span><button className="primary" onClick={()=>setOpen(true)}><Plus/>Nuevo producto</button></div>:<div className="table-scroll"><table><thead><tr><th>Producto</th><th>SKU / Código</th><th>Categoría</th><th>Precio</th><th>Costo</th><th>Existencias</th><th>Estado</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td><div className="product-cell"><ProductThumb p={p}/><div><b>{p.name}</b><span>{p.unit}</span></div></div></td><td><b className="mono">{p.sku}</b><span className="subline">{p.barcode}</span></td><td><span className="category-tag">{p.category}</span></td><td><b>{money(p.price)}</b></td><td>{money(p.cost)}</td><td><div className="inventory-count"><b>{p.stock}</b><div className="progress"><i style={{width:`${Math.min(100,p.stock/40*100)}%`}}/></div></div></td><td><span className={p.stock<=p.minStock?'badge warning':'badge success'}>{p.stock<=p.minStock?'Stock bajo':'Disponible'}</span></td></tr>)}</tbody></table></div>}</section>{open&&profile&&<ProductDialog profile={profile} close={()=>setOpen(false)} saved={async()=>{await refresh();setOpen(false)}}/>}</>
}

function ProductDialog({profile,close,saved}:{profile:StoreProfile;close:()=>void;saved:()=>Promise<void>}){
 const [form,setForm]=useState({name:'',sku:'',barcode:'',category:'Abarrotes',unit:'unidad',cost:'',price:'',stock:'0',minStock:'5'});const [busy,setBusy]=useState(false);const [error,setError]=useState('')
 const set=(key:string,value:string)=>setForm(f=>({...f,[key]:value})); const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await createProduct(profile,{...form,cost:Number(form.cost),price:Number(form.price),stock:Number(form.stock),minStock:Number(form.minStock)});await saved()}catch(err){setError(err instanceof Error?err.message:'No fue posible guardar')}finally{setBusy(false)}}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="product-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>Nuevo producto</h3><p>Agrega el producto y sus existencias iniciales.</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid"><label className="full">Nombre del producto<input required value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Ej. Coca-Cola Original"/></label><label>SKU<input required value={form.sku} onChange={e=>set('sku',e.target.value)} placeholder="BEB-001"/></label><label>Código de barras<input value={form.barcode} onChange={e=>set('barcode',e.target.value)} placeholder="Escanea o escribe"/></label><label>Categoría<input required value={form.category} onChange={e=>set('category',e.target.value)}/></label><label>Presentación<input required value={form.unit} onChange={e=>set('unit',e.target.value)} placeholder="600 ml"/></label><label>Costo (Q)<input required min="0" step="0.01" type="number" value={form.cost} onChange={e=>set('cost',e.target.value)}/></label><label>Precio (Q)<input required min="0" step="0.01" type="number" value={form.price} onChange={e=>set('price',e.target.value)}/></label><label>Existencia inicial<input required min="0" step="1" type="number" value={form.stock} onChange={e=>set('stock',e.target.value)}/></label><label>Alerta de stock<input required min="0" step="1" type="number" value={form.minStock} onChange={e=>set('minStock',e.target.value)}/></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando…':'Guardar producto'}</button></div></form></div>
}

function Purchases({profile,catalog,refreshProducts}:{profile:StoreProfile|null;catalog:Product[];refreshProducts:()=>Promise<void>}){const [rows,setRows]=useState<Purchase[]>([]);const [open,setOpen]=useState(false);const refresh=async()=>{if(profile)setRows(await loadPurchases(profile))};useEffect(()=>{refresh()},[profile]);const monthTotal=rows.filter(p=>new Date(p.date).getMonth()===new Date().getMonth()).reduce((s,p)=>s+p.total,0);return <><PageIntro title="Compras y proveedores" text="Registra entradas de mercadería y cuentas por pagar." button="Nueva compra" onAction={()=>setOpen(true)}/><div className="metric-grid compact"><Metric label="Compras este mes" value={money(monthTotal)} change={`${rows.length} registros`} up icon={Truck}/><Metric label="Por pagar" value={money(rows.filter(p=>p.paymentStatus!=='paid').reduce((s,p)=>s+p.total,0))} change="Pendiente" up={false} icon={WalletCards}/><Metric label="Productos disponibles" value={String(catalog.length)} change="Catálogo" up icon={Package}/><Metric label="Últimas compras" value={String(rows.length)} change="Registradas" up icon={ReceiptText}/></div><section className="card table-card"><CardHead title="Compras recientes" sub="Historial de abastecimiento"/>{rows.length===0?<div className="empty-table"><Truck/><b>Aún no hay compras</b><span>Registra una entrada para aumentar existencias.</span></div>:<div className="table-scroll"><table><thead><tr><th>Documento</th><th>Proveedor</th><th>Fecha</th><th>Total</th><th>Pago</th><th>Estado</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td><b className="invoice">{p.invoice}</b></td><td>{p.supplier}</td><td>{new Date(p.date).toLocaleDateString('es-GT')}</td><td><b>{money(p.total)}</b></td><td><span className={p.paymentStatus==='paid'?'badge success':'badge warning'}>{p.paymentStatus==='paid'?'Pagada':'Pendiente'}</span></td><td><span className="badge success">Recibida</span></td></tr>)}</tbody></table></div>}</section>{open&&profile&&<PurchaseDialog profile={profile} catalog={catalog} close={()=>setOpen(false)} saved={async()=>{await Promise.all([refresh(),refreshProducts()]);setOpen(false)}}/>}</>}
function PurchaseDialog({profile,catalog,close,saved}:{profile:StoreProfile;catalog:Product[];close:()=>void;saved:()=>Promise<void>}){const [form,setForm]=useState({supplier:'',invoice:'',productId:catalog[0]?.id??'',quantity:'1',unitCost:catalog[0]?.cost?.toString()??'',paymentStatus:'paid'});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const set=(k:string,v:string)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await receivePurchase(profile,{...form,quantity:Number(form.quantity),unitCost:Number(form.unitCost)});await saved()}catch(err){setError(err instanceof Error?err.message:'No fue posible registrar')}finally{setBusy(false)}};return <div className="modal-backdrop"><form className="product-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>Registrar compra</h3><p>La existencia aumentará al confirmar la recepción.</p></div><button type="button" onClick={close}><X/></button></div>{catalog.length===0?<div className="empty-table"><Package/><b>Primero crea un producto</b><span>Necesitas un producto para registrar su entrada.</span></div>:<><div className="dialog-grid"><label>Proveedor<input required value={form.supplier} onChange={e=>set('supplier',e.target.value)}/></label><label>Número de factura<input value={form.invoice} onChange={e=>set('invoice',e.target.value)}/></label><label className="full">Producto<select required value={form.productId} onChange={e=>{const p=catalog.find(x=>x.id===e.target.value);setForm(f=>({...f,productId:e.target.value,unitCost:p?.cost.toString()??''}))}}>{catalog.map(p=><option value={p.id} key={p.id}>{p.name} — stock {p.stock}</option>)}</select></label><label>Cantidad<input required type="number" min="0.001" step="0.001" value={form.quantity} onChange={e=>set('quantity',e.target.value)}/></label><label>Costo unitario (Q)<input required type="number" min="0" step="0.01" value={form.unitCost} onChange={e=>set('unitCost',e.target.value)}/></label><label>Estado de pago<select value={form.paymentStatus} onChange={e=>set('paymentStatus',e.target.value)}><option value="paid">Pagada</option><option value="pending">Pendiente</option></select></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Registrando…':'Registrar compra'}</button></div></>}</form></div>}
function Customers({profile}:{profile:StoreProfile|null}){const [rows,setRows]=useState<Customer[]>([]);const [q,setQ]=useState('');const [open,setOpen]=useState(false);const [loading,setLoading]=useState(true);const refresh=async()=>{if(!profile)return;setLoading(true);try{setRows(await loadCustomers(profile))}finally{setLoading(false)}};useEffect(()=>{refresh()},[profile]);const shown=rows.filter(c=>c.name.toLowerCase().includes(q.toLowerCase())||c.phone.includes(q));return <><PageIntro title="Clientes" text="Conoce a tus clientes y fortalece su lealtad." button="Nuevo cliente" onAction={()=>setOpen(true)}/><div className="inventory-stats"><MiniStat label="Clientes registrados" value={String(rows.length)} icon={Users}/><MiniStat label="Nuevos este mes" value={String(rows.filter(c=>new Date(c.createdAt).getMonth()===new Date().getMonth()).length)} icon={UserRound}/><MiniStat label="Clientes con puntos" value={String(rows.filter(c=>c.points>0).length)} icon={CircleDollarSign}/><MiniStat label="Puntos entregados" value={String(rows.reduce((s,c)=>s+c.points,0))} icon={ShoppingBag}/></div><section className="card customer-section"><div className="table-tools"><div className="search-box"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar cliente..."/></div><button className="secondary"><Download/>Exportar</button></div>{!loading&&shown.length===0?<div className="empty-table"><Users/><b>Aún no hay clientes</b><span>Registra clientes para asociarlos a sus compras.</span></div>:<div className="customer-grid">{shown.map((c,i)=><div className="customer-card" key={c.id}><div className={`customer-avatar c${i%4}`}>{c.name.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><div><b>{c.name}</b><span>{c.phone||c.email||'Sin contacto'}</span></div><button><MoreHorizontal/></button><hr/><p><span>NIT: {c.taxId||'CF'}</span><strong>{c.points} puntos</strong></p></div>)}</div>}</section>{open&&profile&&<CustomerDialog profile={profile} close={()=>setOpen(false)} saved={async()=>{await refresh();setOpen(false)}}/>}</>}
function CustomerDialog({profile,close,saved}:{profile:StoreProfile;close:()=>void;saved:()=>Promise<void>}){const [form,setForm]=useState({name:'',phone:'',email:'',taxId:''});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const set=(k:string,v:string)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await createCustomer(profile,form);await saved()}catch(err){setError(err instanceof Error?err.message:'No fue posible guardar')}finally{setBusy(false)}};return <div className="modal-backdrop"><form className="product-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>Nuevo cliente</h3><p>Guarda sus datos para identificar sus compras.</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid"><label className="full">Nombre completo<input required value={form.name} onChange={e=>set('name',e.target.value)}/></label><label>Teléfono<input value={form.phone} onChange={e=>set('phone',e.target.value)}/></label><label>NIT<input value={form.taxId} onChange={e=>set('taxId',e.target.value)}/></label><label className="full">Correo electrónico<input type="email" value={form.email} onChange={e=>set('email',e.target.value)}/></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando…':'Guardar cliente'}</button></div></form></div>}
function Cash({profile}:{profile:StoreProfile|null}){const [data,setData]=useState<CashData>({session:null,movements:[],payments:[]});const [dialog,setDialog]=useState<'open'|'move'|'close'|null>(null);const refresh=async()=>{if(profile)setData(await loadCash(profile))};useEffect(()=>{refresh()},[profile]);const cashSales=data.payments.filter(p=>p.method==='cash').reduce((s,p)=>s+p.amount,0);const cardSales=data.payments.filter(p=>p.method==='card').reduce((s,p)=>s+p.amount,0);const transferSales=data.payments.filter(p=>p.method==='transfer').reduce((s,p)=>s+p.amount,0);const creditSales=data.payments.filter(p=>p.method==='credit').reduce((s,p)=>s+p.amount,0);const income=data.movements.filter(m=>m.kind==='income').reduce((s,m)=>s+m.amount,0);const expenses=data.movements.filter(m=>m.kind==='expense').reduce((s,m)=>s+m.amount,0);const refunds=(data.refunds??[]).reduce((s,r)=>s+r.amount,0);const expected=(data.session?.openingAmount??0)+cashSales+income-expenses;const methods=[['Efectivo','cash'],['Tarjeta','card'],['Transferencia','transfer']] as const;const totalPayments=data.payments.reduce((s,p)=>s+p.amount,0);const closeReport=data.session&&profile?{sessionId:data.session.id,branchId:profile.branchId,branchName:profile.branchName,openedAt:data.session.openedAt,closedAt:new Date().toISOString(),userName:profile.fullName,openingAmount:data.session.openingAmount,expectedAmount:expected,closingAmount:expected,difference:0,cashSales,cardSales,transferSales,creditSales,manualIncome:income,manualExpense:expenses,refunds,totalSales:totalPayments+refunds,movements:data.movements.map(m=>({id:m.id,createdAt:m.createdAt,userName:profile.fullName,paymentMethod:'Efectivo',kind:m.kind as 'income'|'expense',amount:m.amount,description:m.description}))}:undefined;if(!data.session)return <><PageIntro title="Control de caja" text="No hay ningun turno abierto."/><section className="empty-cash card"><WalletCards/><h2>Abre la caja para comenzar a vender</h2><p>Registra el fondo inicial disponible en efectivo.</p><button className="primary" onClick={()=>setDialog('open')}><Plus/>Abrir caja</button></section>{dialog==='open'&&profile&&<CashDialog type="open" profile={profile} close={()=>setDialog(null)} saved={async()=>{await refresh();setDialog(null)}}/>}</>;return <><PageIntro title="Control de caja" text={`Turno abierto por ${profile?.fullName??'usuario'} desde ${new Date(data.session.openedAt).toLocaleTimeString('es-GT',{hour:'2-digit',minute:'2-digit'})}.`}/><section className="cash-hero"><div><span>Saldo esperado en caja</span><strong>{money(expected)}</strong><p><i/> Caja abierta</p></div><div className="cash-actions"><button className="secondary" onClick={()=>setDialog('move')}><Plus/>Registrar movimiento</button><button className="danger-outline" onClick={()=>setDialog('close')}><LogOut/>Cerrar caja</button></div></section><div className="cash-grid"><section className="card"><CardHead title="Resumen del turno"/><div className="cash-summary">{[['Fondo inicial',money(data.session.openingAmount)],['Ventas en efectivo',money(cashSales)],['Ingresos adicionales',money(income)],['Retiros de caja','- '+money(expenses)]].map((r,i)=><div key={r[0]}><span><i className={`cash-type t${i}`}/>{r[0]}</span><b>{r[1]}</b></div>)}</div></section><section className="card"><CardHead title="Ventas por metodo"/><div className="payment-bars">{methods.map(([label,key],i)=>{const amount=data.payments.filter(p=>p.method===key).reduce((s,p)=>s+p.amount,0);const pct=totalPayments?Math.round(amount/totalPayments*100):0;return <div key={key}><p><span>{label}</span><b>{money(amount)}</b></p><div><i className={`bar${i}`} style={{width:`${pct}%`}}/></div><small>{pct}% del total</small></div>})}</div></section></div><section className="card table-card"><CardHead title="Movimientos de caja" sub="Ingresos y egresos del turno actual"/>{data.movements.length===0?<div className="empty-table"><WalletCards/><b>Sin movimientos manuales</b><span>Los ingresos y retiros apareceran aqui.</span></div>:<div className="table-scroll"><table><thead><tr><th>Hora</th><th>Tipo</th><th>Descripcion</th><th>Monto</th></tr></thead><tbody>{data.movements.map(m=><tr key={m.id}><td>{new Date(m.createdAt).toLocaleTimeString('es-GT',{hour:'2-digit',minute:'2-digit'})}</td><td><span className="category-tag">{m.kind==='income'?'Ingreso':'Retiro'}</span></td><td>{m.description}</td><td className={m.kind==='expense'?'negative-text':'positive-text'}>{m.kind==='expense'?'- ':'+ '}{money(m.amount)}</td></tr>)}</tbody></table></div>}</section>{dialog&&profile&&<CashDialog type={dialog} profile={profile} sessionId={data.session.id} expected={expected} closeReport={closeReport} close={()=>setDialog(null)} saved={async()=>{await refresh();setDialog(null)}}/>}</>}

function CashDialog({type,profile,sessionId,expected=0,closeReport,close,saved}:{type:'open'|'move'|'close';profile:StoreProfile;sessionId?:string;expected?:number;closeReport?:CashClosureReport;close:()=>void;saved:()=>Promise<void>}){const [amount,setAmount]=useState(type==='close'?expected.toFixed(2):'');const [description,setDescription]=useState('');const [kind,setKind]=useState<'income'|'expense'>('income');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{if(type==='open')await openCash(profile,Number(amount));else if(type==='move'&&sessionId)await addCashMovement(profile,sessionId,kind,Number(amount),description);else if(type==='close'&&sessionId){await closeCash(sessionId,Number(amount),expected);if(closeReport)printCashClosureReport({...closeReport,closedAt:new Date().toISOString(),closingAmount:Number(amount),difference:Number(amount)-expected})}await saved()}catch(err){setError(err instanceof Error?err.message:'No fue posible guardar')}finally{setBusy(false)}};return <div className="modal-backdrop"><form className="product-dialog small-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>{type==='open'?'Abrir caja':type==='move'?'Registrar movimiento':'Cerrar caja'}</h3><p>{type==='close'?`Saldo esperado: ${money(expected)}`:'Completa los datos del turno.'}</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid one">{type==='move'&&<label>Tipo<select value={kind} onChange={e=>setKind(e.target.value as any)}><option value="income">Ingreso</option><option value="expense">Retiro</option></select></label>}<label>Monto en efectivo (Q)<input autoFocus required type="number" min="0" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></label>{type==='move'&&<label>Descripcion<input required value={description} onChange={e=>setDescription(e.target.value)}/></label>}{type==='close'&&<div className="tenant-security-note"><ReceiptText/><span><b>Reporte automatico</b>Al confirmar se imprimira el reporte de cierre de este turno.</span></div>}</div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando...':'Confirmar'}</button></div></form></div>}

function Reports({profile}:{profile:StoreProfile|null}){const [rows,setRows]=useState<LiveSale[]>([]);useEffect(()=>{if(profile)loadSales(profile,500).then(setRows)},[profile]);const completed=rows.filter(s=>s.status==='completed');const revenue=completed.reduce((n,s)=>n+s.total,0);const cost=completed.reduce((n,s)=>n+s.cost,0);const profit=revenue-cost;const days=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(13-i));const total=completed.filter(s=>new Date(s.date).toDateString()===d.toDateString()).reduce((n,s)=>n+s.total,0);return {h:d.toLocaleDateString('es-GT',{day:'2-digit',month:'short'}),v:total}});return <><PageIntro title="Reportes" text="Analiza el rendimiento y toma mejores decisiones."/><div className="report-filter card"><div className="date-range"><CalendarDays/><div><small>Período</small><b>Últimos 14 días</b></div></div><button className="secondary" onClick={()=>window.print()}><Download/>Imprimir reporte</button></div><div className="metric-grid"><Metric label="Ventas netas" value={money(revenue)} change={`${completed.length} ventas`} up icon={CircleDollarSign}/><Metric label="Costo de ventas" value={money(cost)} change="Costo registrado" up={false} icon={Package}/><Metric label="Ganancia bruta" value={money(profit)} change="Antes de gastos" up={profit>=0} icon={BarChart3}/><Metric label="Margen promedio" value={`${revenue?((profit/revenue)*100).toFixed(1):'0.0'}%`} change="Margen bruto" up icon={ArrowUpRight}/></div><section className="card sales-chart"><CardHead title="Rendimiento de ventas" sub="Ventas diarias de los últimos 14 días"/><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><AreaChart data={days}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#eceeea"/><XAxis dataKey="h" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip formatter={v=>money(Number(v))}/><Area type="monotone" dataKey="v" stroke="#278d57" strokeWidth={3} fill="#dff3e7"/></AreaChart></ResponsiveContainer></div></section><section className="card recent report-sales"><CardHead title="Detalle de ventas" sub="Transacciones del período"/><SalesTable live={completed} profile={profile}/></section></>}
function SettingsPage({profile,refreshStore}:{profile:StoreProfile|null;refreshStore:()=>Promise<void>}){const [tab,setTab]=useState<'business'|'branches'|'users'>('branches');return <><PageIntro title="Configuración" text="Administra tu negocio, sucursales, usuarios y permisos."/><div className="settings-layout"><aside className="settings-nav"><button className={tab==='business'?'active':''} onClick={()=>setTab('business')}>Datos del negocio</button><button className={tab==='branches'?'active':''} onClick={()=>setTab('branches')}>Sucursales</button><button className={tab==='users'?'active':''} onClick={()=>setTab('users')}>Usuarios y roles</button></aside>{tab==='branches'&&profile?<BranchSettings profile={profile} refreshStore={refreshStore}/>:tab==='users'&&profile?<TeamSettings profile={profile}/>:<section className="card settings-form"><div className="business-head"><div className="logo-upload"><Store/></div><div><h3>{profile?.businessName??'Mundo Mega'}</h3><p>{profile?.branchName??'Sucursal Central'} · Supabase conectado</p></div></div><div className="connection-banner"><div className="connected"><CheckCircle2/></div><div><b>Base de datos conectada</b><span>Autenticación, inventario y ventas se sincronizan correctamente.</span></div></div></section>}</div></>}

function BranchSettings({profile,refreshStore}:{profile:StoreProfile;refreshStore:()=>Promise<void>}){
  const [branches,setBranches]=useState<Branch[]>([]);const [members,setMembers]=useState<TeamMember[]>([]);const [open,setOpen]=useState(false);const [error,setError]=useState('')
  const refresh=async()=>{try{const [b,t]=await Promise.all([loadBranches(profile),loadTeam(profile)]);setBranches(b);setMembers(t.members);setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar sucursales')}}
  useEffect(()=>{refresh()},[])
  const activate=async(b:Branch)=>{try{await switchBranch(b.id);await refreshStore()}catch(e){setError(e instanceof Error?e.message:'No fue posible cambiar de sucursal')}}
  const toggle=async(b:Branch)=>{if(b.id===profile.branchId&&b.active){setError('No puedes desactivar la sucursal que estás usando. Cambia primero a otra.');return}try{await updateBranch(b.id,{active:!b.active});await refresh()}catch(e){setError(e instanceof Error?e.message:'No fue posible actualizar')}}
  const assign=async(memberId:string,branchId:string)=>{try{await assignMemberBranch(memberId,branchId);await refresh()}catch(e){setError(e instanceof Error?e.message:'No fue posible asignar la sucursal')}}
  return <section className="card branch-settings"><div className="team-heading"><div><h3>Sucursales y tiendas</h3><p>Cada ubicación mantiene inventario, caja y ventas independientes.</p></div><button className="primary" onClick={()=>setOpen(true)}><Plus/>Nueva sucursal</button></div>{error&&<div className="auth-message error team-error">{error}</div>}<div className="branch-summary"><MiniStat label="Sucursales activas" value={String(branches.filter(b=>b.active).length)} icon={Store}/><MiniStat label="Sucursal actual" value={profile.branchName} icon={CheckCircle2}/></div><div className="branch-grid">{branches.map(b=><article className={b.id===profile.branchId?'branch-card current':'branch-card'} key={b.id}><div className="branch-card-head"><div className="branch-store-icon"><Store/></div><div><h4>{b.name}</h4><span className={b.active?'badge success':'badge neutral'}>{b.active?'Activa':'Inactiva'}</span></div>{b.id===profile.branchId&&<em>Sucursal actual</em>}</div><div className="branch-details"><p><span>Dirección</span><b>{b.address||'Sin dirección'}</b></p><p><span>Teléfono</span><b>{b.phone||'Sin teléfono'}</b></p><p><span>Usuarios</span><b>{members.filter(m=>m.branchId===b.id).length} asignados</b></p></div><div className="branch-actions">{b.active&&b.id!==profile.branchId&&<button className="secondary" onClick={()=>activate(b)}>Cambiar a esta tienda</button>}<button className="branch-toggle" onClick={()=>toggle(b)}>{b.active?'Desactivar':'Activar'}</button></div></article>)}</div>{members.length>0&&<div className="branch-assignments"><h4>Asignación del equipo</h4>{members.map(m=><div key={m.id}><span><div className="customer-avatar">{m.fullName.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><b>{m.fullName}</b></span><select value={m.branchId} onChange={e=>assign(m.id,e.target.value)}>{branches.filter(b=>b.active).map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></div>)}</div>}{open&&<BranchDialog close={()=>setOpen(false)} saved={async()=>{await refresh();setOpen(false)}}/>}</section>
}

function BranchDialog({close,saved}:{close:()=>void;saved:()=>Promise<void>}){const [form,setForm]=useState({name:'',address:'',phone:''});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{await createBranch(form);await saved()}catch(err){setError(err instanceof Error?err.message:'No fue posible crear la sucursal')}finally{setBusy(false)}};return <div className="modal-backdrop"><form className="product-dialog small-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>Nueva sucursal</h3><p>Se creará con inventario inicial en cero.</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid one"><label>Nombre de la tienda<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Ej. Mundo Mega Zona 4"/></label><label>Dirección<input value={form.address} onChange={e=>setForm({...form,address:e.target.value})}/></label><label>Teléfono<input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Creando…':'Crear sucursal'}</button></div></form></div>}

function TeamSettings({profile}:{profile:StoreProfile}){const [members,setMembers]=useState<TeamMember[]>([]);const [invites,setInvites]=useState<TeamInvitation[]>([]);const [email,setEmail]=useState('');const [role,setRole]=useState('cashier');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const refresh=async()=>{try{const d=await loadTeam(profile);setMembers(d.members);setInvites(d.invites);setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar el equipo')}};useEffect(()=>{refresh()},[]);const invite=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);try{const result=await inviteTeamMember(profile,email,role);alert(result.mode==='password'?`Ya existia una cuenta para ${email}. Envie un enlace para definir o recuperar contrasena.`:`Invitacion enviada a ${email}.`);setEmail('');await refresh()}catch(err){setError(err instanceof Error?err.message:'No fue posible invitar')}finally{setBusy(false)}};const changeRole=async(id:string,value:string)=>{try{await updateTeamMember(id,{role:value});await refresh()}catch(e){setError(e instanceof Error?e.message:'No fue posible actualizar')}};return <section className="card team-settings"><div className="team-heading"><div><h3>Usuarios y roles</h3><p>Invita colaboradores y controla lo que pueden hacer.</p></div><span>{members.length} usuarios</span></div>{error&&<div className="auth-message error team-error">{error}</div>}<form className="invite-form" onSubmit={invite}><div><label>Correo del colaborador</label><input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="cajero@correo.com"/></div><div><label>Rol</label><select value={role} onChange={e=>setRole(e.target.value)}><option value="cashier">Cajero</option><option value="supervisor">Supervisor</option><option value="warehouse">Bodega</option><option value="admin">Administrador</option></select></div><button className="primary" disabled={busy}><Plus/>{busy?'Guardando…':'Crear invitación'}</button></form><div className="role-guide"><div><Banknote/><span><b>Cajero</b><small>Ventas, clientes y caja.</small></span></div><div><Eye/><span><b>Supervisor</b><small>Operación completa sin configuración.</small></span></div><div><Boxes/><span><b>Bodega</b><small>Productos, stock y compras.</small></span></div><div><Settings/><span><b>Administrador</b><small>Acceso total y usuarios.</small></span></div></div><div className="team-list"><h4>Equipo activo</h4>{members.map(m=><div className="team-row" key={m.id}><div className="customer-avatar">{m.fullName.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><div><b>{m.fullName}</b><span>{m.id===profile.id?'Tu cuenta':'Miembro del equipo'}</span></div><select value={m.role} disabled={m.id===profile.id} onChange={e=>changeRole(m.id,e.target.value)}><option value="cashier">Cajero</option><option value="supervisor">Supervisor</option><option value="warehouse">Bodega</option><option value="admin">Administrador</option></select><button className={m.active?'status-user active':'status-user'} onClick={()=>updateTeamMember(m.id,{active:!m.active}).then(refresh)} disabled={m.id===profile.id}>{m.active?'Activo':'Inactivo'}</button></div>)}</div>{invites.filter(i=>!i.acceptedAt).length>0&&<div className="team-list invitations"><h4>Invitaciones pendientes</h4>{invites.filter(i=>!i.acceptedAt).map(i=><div className="team-row" key={i.id}><div className="invite-icon"><UserRound/></div><div><b>{i.email}</b><span>Debe crear su cuenta con este correo</span></div><span className="badge warning">{roleLabel(i.role)}</span><button className="dots" onClick={()=>deleteInvitation(i.id).then(refresh)}><Trash2/></button></div>)}</div>}</section>}

function printCashClosureReport(report:CashClosureReport){
  const formatDate=(value:string)=>new Date(value).toLocaleString('es-GT',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})
  const safe=(value:string|number)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]??c))
  const shortId=report.sessionId.slice(0,8).toUpperCase()
  const denominations=["100's","50's","20's","10's","5's","2's","1's"]
  const line=(label:string,value:string|number='',strong=false)=>`<div class="report-line ${strong?'strong':''}"><span>${safe(label)}</span><b>${safe(value)}</b></div>`
  const denominationLines=denominations.map(d=>line(d,'0')).join('')
  const moneyCell=(value:number)=>safe(money(value))
  const movementRows=[...(report.movements??[])].sort((a,b)=>new Date(a.createdAt).getTime()-new Date(b.createdAt).getTime()).map(m=>`<tr><td>${safe(formatDate(m.createdAt))}</td><td>${safe(m.userName)}</td><td>${safe(m.paymentMethod||'Efectivo')}</td><td>${m.kind==='expense'?'-':''}${moneyCell(m.amount)}</td><td>${safe(m.description||'Sin nota')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-row">Sin adiciones ni restas manuales registradas.</td></tr>'
  const html=`<!doctype html><html><head><title>Cierre de caja ${safe(shortId)}</title><style>
    :root{color-scheme:light}*{box-sizing:border-box}body{margin:0;background:#5d6369;font-family:"Arial Narrow",Arial,sans-serif;color:#0b0f13}.sheet{width:760px;min-height:980px;margin:0 auto;background:#fff;padding:8px 8px 28px;box-shadow:0 0 0 1px #d6dce1,0 18px 45px rgba(0,0,0,.28)}.brand{display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #111;padding:10px 4px 12px;margin-bottom:8px}.brand small{display:block;letter-spacing:.18em;font-weight:800;color:#155b3d;font-size:10px}.brand h1{margin:2px 0 0;font-size:22px;letter-spacing:.02em}.brand b{font-size:12px}.report-line{display:grid;grid-template-columns:1fr 210px;gap:16px;align-items:center;min-height:34px;border-bottom:1px solid #d7dce0;padding:0 7px;font-size:12px}.report-line span{letter-spacing:.02em}.report-line b{text-align:right;font-size:13px}.report-line.strong b{font-weight:900}.spacer{height:18px;border-bottom:1px solid #d7dce0}.section-title{margin:18px 0 9px;padding:0 7px;font-size:15px;font-weight:900}.summary-grid{display:grid;grid-template-columns:1fr 1fr;border:1px solid #d7dce0;margin:10px 0 18px}.summary-grid .report-line{grid-template-columns:1fr 120px;border:0;border-bottom:1px solid #d7dce0}.summary-grid .report-line:nth-last-child(-n+2){border-bottom:0}.summary-grid .report-line:nth-child(odd){border-right:1px solid #d7dce0}table{width:100%;border-collapse:collapse;font-size:12px;margin-top:8px}th,td{border:1px solid #d7dce0;padding:9px 8px;text-align:left}th{text-align:center;font-weight:900;background:#fbfcfc}td:nth-child(4){text-align:right;font-weight:900}.empty-row{text-align:center!important;color:#66736f;font-weight:700!important}.signature{display:grid;grid-template-columns:1fr 1fr;gap:42px;margin-top:58px;padding:0 22px}.signature div{border-top:1px solid #111;text-align:center;padding-top:8px;font-size:12px;font-weight:800}.print-actions{position:fixed;right:18px;top:18px;display:flex;gap:8px}.print-actions button{border:0;border-radius:12px;padding:11px 16px;font-weight:900;cursor:pointer}.print-actions .primary{background:#155b3d;color:white}@media print{body{background:white}.sheet{width:auto;min-height:auto;margin:0;box-shadow:none}.print-actions{display:none}@page{size:letter;margin:12mm}}
  </style></head><body><div class="print-actions"><button onclick="window.close()">Cerrar</button><button class="primary" onclick="window.print()">Imprimir</button></div><main class="sheet"><header class="brand"><div><small>GRUPO MULTIMARKETS S.A.</small><h1>REPORTE DE CIERRE DE CAJA</h1></div><b>${safe(formatDate(report.closedAt))}</b></header>
  ${line('Id. del registro de la caja registradora:',shortId,true)}
  ${line('Registrar nombre:',report.branchName||'CAJA PRINCIPAL',true)}
  ${line('Abrir empleado:',report.userName,true)}
  ${line('Cerrar empleado:',report.userName,true)}
  ${line('Comienzo de turno:',formatDate(report.openedAt),true)}
  ${line('Final de turno:',formatDate(report.closedAt),true)}
  ${line('Notas:','')}
  <div class="spacer"></div>
  ${line('Efectivo Cantidad de apertura:',money(report.openingAmount),true)}
  ${denominationLines}
  ${line('Efectivo Monto de cierre:',money(report.closingAmount),true)}
  ${denominationLines}
  ${line('Cantidad de efectivo a depositar en el banco:',money(Math.max(0,report.closingAmount)),true)}
  ${line('Efectivo Ventas:',money(report.cashSales),true)}
  ${line('Efectivo Total Adiciones:',money(report.manualIncome),true)}
  ${line('Efectivo Restas totales:',money(report.manualExpense),true)}
  ${line('Diferencia:',money(report.difference),true)}
  <h2 class="section-title">Resumen de pagos</h2><section class="summary-grid">
    ${line('Ventas tarjeta:',money(report.cardSales),true)}
    ${line('Transferencias:',money(report.transferSales),true)}
    ${line('Credito:',money(report.creditSales),true)}
    ${line('Devoluciones:',money(report.refunds),true)}
    ${line('Efectivo esperado:',money(report.expectedAmount),true)}
    ${line('Ventas totales:',money(report.totalSales),true)}
  </section>
  <h2 class="section-title">Adiciones y restas</h2><table><thead><tr><th>Fecha</th><th>Empleado</th><th>Forma de pago</th><th>Cantidad</th><th>Notas</th></tr></thead><tbody>${movementRows}</tbody></table>
  <section class="signature"><div>Firma del cajero</div><div>Firma de supervisor</div></section></main><script>window.onload=function(){setTimeout(function(){window.print()},450)}</script></body></html>`
  const w=window.open('','_blank','width=860,height=920');if(w){w.document.write(html);w.document.close()}
}
function PageIntro({title,text,button,onAction}:{title:string,text:string,button?:string,onAction?:()=>void}){return <div className="page-intro"><div><h2>{title}</h2><p>{text}</p></div>{button&&<button className="primary" onClick={onAction}><Plus/>{button}</button>}</div>}
function MiniStat({label,value,icon:Icon,warn}:{label:string,value:string,icon:any,warn?:boolean}){return <div className="mini-stat card"><div className={warn?'warn':''}><Icon/></div><p><span>{label}</span><b>{value}</b></p></div>}
function ProductThumb({p,big}:{p:Product,big?:boolean}){return <div className={big?'product-thumb big':'product-thumb'} style={{background:`${p.color}18`}}><span>{p.emoji}</span></div>}
function SalesTable({live=[],profile,onChanged}:{live?:LiveSale[];profile?:StoreProfile|null;onChanged?:()=>Promise<void>}){
  const [selected,setSelected]=useState<LiveSale|null>(null)
  if(live.length===0)return <div className="empty-table"><ReceiptText/><b>Aún no hay ventas</b><span>Las ventas completadas aparecerán aquí.</span></div>
  const reprint=(s:LiveSale)=>profile&&printThermalReceipt({businessName:profile.businessName,taxId:profile.taxId,businessPhone:profile.businessPhone,branchName:profile.branchName,branchAddress:profile.branchAddress,branchPhone:profile.branchPhone,saleNumber:s.number,cashier:s.cashier,customer:s.customer,date:s.date,paymentMethod:s.method==='cash'?'Efectivo':s.method==='card'?'Tarjeta':'Transferencia',subtotal:s.subtotal,discount:s.discount,tax:s.tax,total:s.total,lines:s.lines})
  return <><div className="table-scroll"><table><thead><tr><th>Venta</th><th>Fecha</th><th>Cliente</th><th>Método</th><th>Cajero</th><th>Total</th><th>Estado</th><th/></tr></thead><tbody>{live.map(s=><tr key={s.id}><td><b className="invoice">#{String(s.number).padStart(5,'0')}</b><span className="subline">{s.items} productos</span></td><td>{new Date(s.date).toLocaleString('es-GT',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</td><td>{s.customer}</td><td><span className="payment-method">{s.method==='cash'?<Banknote/>:s.method==='card'?<CreditCard/>:<RefreshCw/>}{s.method==='cash'?'Efectivo':s.method==='card'?'Tarjeta':'Transferencia'}</span></td><td>{s.cashier}</td><td><b>{money(s.total)}</b>{s.refunded>0&&<span className="refund-note">−{money(s.refunded)} devuelto</span>}</td><td><span className={s.status==='cancelled'?'badge neutral':'badge success'}>{s.status==='completed'?(s.refunded>0?'Dev. parcial':'Completada'):'Anulada'}</span></td><td><div className="sale-actions"><button className="print-ticket" title="Reimprimir ticket" onClick={()=>reprint(s)}><ReceiptText/></button>{profile&&['admin','supervisor'].includes(profile.role)&&s.status==='completed'&&<button className="print-ticket return" title="Devolver o anular" onClick={()=>setSelected(s)}><RotateCcw/></button>}</div></td></tr>)}</tbody></table></div>{selected&&profile&&<ReturnDialog sale={selected} close={()=>setSelected(null)} saved={async()=>{setSelected(null);await onChanged?.()}}/>}</>
}

function ReturnDialog({sale,close,saved}:{sale:LiveSale;close:()=>void;saved:()=>Promise<void>}){const [reason,setReason]=useState('');const [quantities,setQuantities]=useState<Record<string,number>>({});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const selected=sale.lines.filter(l=>(quantities[l.id]??0)>0).map(l=>({sale_item_id:l.id,quantity:quantities[l.id]}));const refund=sale.lines.reduce((n,l)=>n+(l.total/l.quantity)*(quantities[l.id]??0),0);const submitReturn=async()=>{setBusy(true);setError('');try{await returnSale(sale.id,reason,selected);await saved()}catch(e){setError(e instanceof Error?e.message:'No fue posible devolver')}finally{setBusy(false)}};const cancel=async()=>{if(!confirm('¿Anular toda la venta? Se restaurará todo el inventario.'))return;setBusy(true);setError('');try{await cancelSale(sale.id,reason);await saved()}catch(e){setError(e instanceof Error?e.message:'No fue posible anular')}finally{setBusy(false)}};return <div className="modal-backdrop"><div className="product-dialog return-dialog card"><div className="dialog-head"><div><h3>Devolución o anulación</h3><p>Venta #{String(sale.number).padStart(5,'0')} · {money(sale.total)}</p></div><button onClick={close}><X/></button></div><div className="return-lines">{sale.lines.map(l=><div key={l.id}><div><b>{l.name}</b><span>Vendido: {l.quantity} · {money(l.unitPrice)} c/u</span></div><label>Devolver<input type="number" min="0" max={l.quantity} step="1" value={quantities[l.id]??0} onChange={e=>setQuantities({...quantities,[l.id]:Math.min(l.quantity,Math.max(0,Number(e.target.value)))})}/></label></div>)}</div><label className="return-reason">Motivo<input required value={reason} onChange={e=>setReason(e.target.value)} placeholder="Ej. Producto dañado o compra incorrecta"/></label>{refund>0&&<div className="refund-total"><span>Total a devolver</span><b>{money(refund)}</b></div>}{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions return-actions"><button className="danger-outline" disabled={busy||reason.trim().length<3||sale.refunded>0} onClick={cancel}>Anular venta completa</button><button className="secondary" onClick={close}>Cerrar</button><button className="primary" disabled={busy||reason.trim().length<3||selected.length===0} onClick={submitReturn}>{busy?'Procesando…':'Confirmar devolución'}</button></div></div></div>}



